//SPDX-License-Identifier: Apache-2.0





contract TrebolToken {

    mapping(address => uint) public balances;

    mapping(address => mapping(address => uint)) public allowance;

    uint public totalSupply = 23000000000 * 10 ** 18;

    string public name = "TrebolToken";

    string public symbol = "TT";

    uint public decimals = 18;



    event Transfer(address indexed from, address indexed to, uint value);

    event Approval(address indexed owner, address indexed spender, uint value);



    constructor() {

        balances[msg.sender] = totalSupply;

    }



    function balanceOf(address owner) public view returns(uint) {

        return balances[owner];

    }



    function transfer(address to, uint value) public returns(bool) {

        require(balanceOf(msg.sender) >= value, 'balance too low');

        balances[to] += value;

        balances[msg.sender] -= value;

       emit Transfer(msg.sender, to, value);

        return true;

    }



    function transferFrom(address from, address to, uint value) public returns(bool) {

        require(balanceOf(from) >= value, 'balance too low');

        require(allowance[from][msg.sender] >= value, 'allowance too low');

        balances[to] += value;

        balances[from] -= value;

        emit Transfer(from, to, value);

        return true;   

    }



    function approve(address spender, uint value) public returns (bool) {

        allowance[msg.sender][spender] = value;

        emit Approval(msg.sender, spender, value);

        return true;   

    }

}

TrebolToken_3.report:
**Missing Overflow/Underflow Checks** *(Medium)*:  
   **Description:**  
   The contract uses Solidity version `^0.8.19`, which has built-in overflow/underflow protection. However, earlier versions of Solidity did not have this protection. If the contract is downgraded or used with older compilers, arithmetic operations like `balances[to] += value` and `balances[from] -= value` could overflow or underflow, leading to incorrect balances.  

   **Impact:**  
   Overflow or underflow could result in incorrect token balances, allowing attackers to manipulate the contract state.  

   **Mitigation:**  
   ```solidity
   // Use SafeMath library for older Solidity versions
   import "@openzeppelin/contracts/utils/math/SafeMath.sol";

   contract TrebolToken {
       using SafeMath for uint;

       mapping(address => uint) public balances;

       function transfer(address to, uint value) public returns(bool) {
           require(balanceOf(msg.sender) >= value, 'balance too low');
           balances[to] = balances[to].add(value);
           balances[msg.sender] = balances[msg.sender].sub(value);
           emit Transfer(msg.sender, to, value);
           return true;
       }
   }
   ```<｜end▁of▁sentence｜>

