        public
        view
        returns (uint256 price)
    {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();

        price = (uniswapV2Router.getAmountsOut(amount, path))[path.length - 1];
    }
