            // Account will not receive reflections
            require(!ier[account], "Account is already excluded");
            if(_rOwned[account] > 0) {
                _tOwned[account] = tokenFromReflection(_rOwned[account]);
            }
            ier[account] = true;
                _excluded.push(account);
