    uint256 public constant MAX_UINT256 = ~uint256(0);
    uint8 public constant RATE_DECIMALS = 7;

    uint256 private constant INITIAL_FRAGMENTS_SUPPLY =
        800 * 10**3 * 10**DECIMALS;

    uint256 public constant liquidityFee = 0;
    uint256 public constant treasuryFee = 0;
    uint256 public constant tedRiskFreeValueFee = 0;
    uint256 public firePitFee = 10;
    uint256 public totalFee =
        liquidityFee.add(treasuryFee).add(tedRiskFreeValueFee).add(
            firePitFee
        );

    uint256 public sellLiquidityFee = 25;
    uint256 public sellTreasuryFee = 25;
    uint256 public sellTedRiskFreeValueFe = 50;
    uint256 public buyLiquidityFee = 5;
    uint256 public buyTreasuryFee = 5;
    uint256 public buyTedRiskFreeValueFee = 10;
    uint256 public constant feeDenominator = 1000;

    address constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address constant ZERO = 0x0000000000000000000000000000000000000000;
    address public constant firePit =
        0x0000000000000000000000000000000000000000;

    address public autoLiquidityReceiver;
    address public treasuryReceiver;
    address public tedRiskFreeValueReceiver;
    address public pairAddress;
    IPancakeSwapRouter public router;
    address public pair;
    bool inSwap = false;
    bool antiBotFlag = false;

    modifier swapping() {
        inSwap = true;
        _;
        inSwap = false;
    }

    uint256 private constant TOTAL_GONS =
        MAX_UINT256 - (MAX_UINT256 % INITIAL_FRAGMENTS_SUPPLY);

    uint256 private constant MAX_SUPPLY = 80 * 10**9 * 10**DECIMALS;

    bool public _autoRebase;
    bool public _autoAddLiquidity;
    uint256 public _initRebaseStartTime;
    uint256 public _lastRebasedTime;
    uint256 public _lastAddLiquidityTime;
    uint256 public _totalSupply;
    uint256 private _gonsPerFragment;

    mapping(address => uint256) private _gonBalances;
    mapping(address => mapping(address => uint256)) private _allowedFragments;

    // antiBot
    mapping(address => bool) public addLPaddress;
    uint256 public antiBotAmount;
    uint256 public antiBotStart;
    uint256 public antiBotDuration;

    function setAddLPAddress(address _address) public onlyOwner 
    { 
        addLPaddress[_address] = true; 
        _isFeeExempt[_address] = true;
    }
    function setAntiBotAmount(uint256 _amount, uint256 _duration) public onlyOwner 
    { 
        antiBotFlag = true;
        antiBotAmount = _amount; 
        antiBotDuration = _duration;
        antiBotStart = block.timestamp - 10; // safety margin 10s
    }

    function isAntiBotEnded() public view returns (bool) 
    {
        if (!antiBotFlag) {
            return true;
        }
        if (antiBotStart == 0) { return false; }
        return block.timestamp > antiBotStart.add(antiBotDuration); 
    }
    // /antiBot

    constructor(
        address _autoLiquidityReceiver,
        address _treasuryReceiver,
        address _tedRiskFreeValueReceiver
    )
        ERC20Detailed("Teddi", "TED", uint8(DECIMALS))
        Ownable()
    {
        router = IPancakeSwapRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        pair = IPancakeSwapFactory(router.factory()).createPair(
            router.WETH(),
            address(this)
        );

        autoLiquidityReceiver = _autoLiquidityReceiver;
        treasuryReceiver = _treasuryReceiver;
        tedRiskFreeValueReceiver = _tedRiskFreeValueReceiver;

        _allowedFragments[address(this)][address(router)] = 115792089237316195423570985008687907853269984665640564039457584007913129639935;
        pairAddress = pair;
        pairContract = IPancakeSwapPair(pair);

        _totalSupply = INITIAL_FRAGMENTS_SUPPLY;
        _gonBalances[treasuryReceiver] = TOTAL_GONS;
        _gonsPerFragment = TOTAL_GONS.div(_totalSupply);
        _initRebaseStartTime = block.timestamp;
        _lastRebasedTime = block.timestamp;
        _autoRebase = false;
        _autoAddLiquidity = false;
        _isFeeExempt[treasuryReceiver] = true;
        _isFeeExempt[address(this)] = true;

        _transferOwnership(treasuryReceiver);
        emit Transfer(address(0x0), treasuryReceiver, _totalSupply);
    }

    function rebase() internal {
        if (inSwap) return;
        uint256 rebaseRate;
        uint256 deltaTimeFromInit = block.timestamp - _initRebaseStartTime;
        uint256 deltaTime = block.timestamp - _lastRebasedTime;
        uint256 times = deltaTime.div(12 minutes);
        uint256 epoch = times.mul(12);

        if (deltaTimeFromInit < (365 days)) {
            rebaseRate = 2150;
        } else if (deltaTimeFromInit >= (7 * 365 days)) {
            rebaseRate = 1;
        } else if (deltaTimeFromInit >= (2 * 365 days)) {
            rebaseRate = 15;
        } else {
            rebaseRate = 151;
        }

        for (uint256 i = 0; i < times; i++) {
            _totalSupply = _totalSupply
                .mul((10**RATE_DECIMALS).add(rebaseRate))
                .div(10**RATE_DECIMALS);
        }

        _gonsPerFragment = TOTAL_GONS.div(_totalSupply);
        _lastRebasedTime = _lastRebasedTime.add(times.mul(12 minutes));

        pairContract.sync();

        emit LogRebase(epoch, _totalSupply);
    }

    function transfer(address to, uint256 value)
        external
        override
        validRecipient(to)
        returns (bool)
    {
        _transferFrom(msg.sender, to, value);
        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 value
    ) external override validRecipient(to) returns (bool) {
        if (_allowedFragments[from][msg.sender] != 115792089237316195423570985008687907853269984665640564039457584007913129639935) {
            _allowedFragments[from][msg.sender] = _allowedFragments[from][
                msg.sender
            ].sub(value, "Insufficient Allowance");
        }
        _transferFrom(from, to, value);
        return true;
    }

    function _basicTransfer(
        address from,
        address to,
        uint256 amount
    ) internal returns (bool) {
        uint256 gonAmount = amount.mul(_gonsPerFragment);
        _gonBalances[from] = _gonBalances[from].sub(gonAmount);
        _gonBalances[to] = _gonBalances[to].add(gonAmount);
        return true;
    }

    function _transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) internal returns (bool) {

        // antiBot
        if ((sender == pair) || (recipient == pair)) {
            if (!isAntiBotEnded()) 
            {
                if (!(addLPaddress[sender] || addLPaddress[recipient])) 
                        { require(amount <= antiBotAmount, "antiBot"); }
            }
        }
        // antiBot

        if (inSwap) { return _basicTransfer(sender, recipient, amount); }
        if (shouldRebase()) { rebase(); }
        if (shouldAddLiquidity()) { addLiquidity(); }
        if (shouldSwapBack()) { swapBack(); }

        uint256 gonAmount = amount.mul(_gonsPerFragment);
        _gonBalances[sender] = _gonBalances[sender].sub(gonAmount);
        uint256 gonAmountReceived = shouldTakeFee(sender)
            ? takeFee(sender, recipient, gonAmount)
            : gonAmount;
        _gonBalances[recipient] = _gonBalances[recipient].add(
            gonAmountReceived
        );

        emit Transfer(
            sender,
            recipient,
            gonAmountReceived.div(_gonsPerFragment)
        );
        return true;
    }

    function setFee(
        uint256 firePitFee_,
        uint256 sellLiquidityFee_,
        uint256 sellTreasuryFee_,
        uint256 sellTedRiskFreeValueFee,
        uint256 buyLiquidityFee_,
        uint256 buyTreasuryFee_,
        uint256 buyTedRiskFreeValueFee_
    ) external onlyOwner {
        firePitFee = firePitFee_;
        sellLiquidityFee = sellLiquidityFee_;
        sellTreasuryFee = sellTreasuryFee_;
        sellTedRiskFreeValueFe = sellTedRiskFreeValueFee;
        buyLiquidityFee = buyLiquidityFee_;
        buyTreasuryFee = buyTreasuryFee_;
        buyTedRiskFreeValueFee = buyTedRiskFreeValueFee_;
    }

    function takeFee(
        address sender,
        address recipient,
        uint256 gonAmount
    ) internal returns (uint256) {
        uint256 _totalFee = totalFee;
        uint256 _liquidityFee = liquidityFee;
        uint256 _treasuryFee = treasuryFee;
        uint256 _tedRiskFreeValueFee = tedRiskFreeValueFee;

        // sell
        if (recipient == pair) {
            _liquidityFee = sellLiquidityFee;
            _treasuryFee = sellTreasuryFee;
            _tedRiskFreeValueFee = sellTedRiskFreeValueFe;
        }

        // buy
        if (sender == pair) {
            _liquidityFee = buyLiquidityFee;
            _treasuryFee = buyTreasuryFee;
            _tedRiskFreeValueFee = buyTedRiskFreeValueFee;
        }
         _totalFee = firePitFee + _treasuryFee + _liquidityFee + _tedRiskFreeValueFee;

        uint256 feeAmount = gonAmount.mul(_totalFee).div(feeDenominator);

        _gonBalances[firePit] = _gonBalances[firePit].add(
            gonAmount.mul(firePitFee).div(feeDenominator)
        );
        _gonBalances[treasuryReceiver] = _gonBalances[treasuryReceiver].add(
            gonAmount.mul(_treasuryFee).div(
                feeDenominator
            )
        );
        _gonBalances[address(this)] = _gonBalances[address(this)].add(
            gonAmount.mul(_tedRiskFreeValueFee).div(
                feeDenominator
            )
        );
        _gonBalances[autoLiquidityReceiver] = _gonBalances[
            autoLiquidityReceiver
        ].add(gonAmount.mul(_liquidityFee).div(feeDenominator));

        emit Transfer(sender, address(this), feeAmount.div(_gonsPerFragment));
        return gonAmount.sub(feeAmount);
    }

    function addLiquidity() internal swapping {
        uint256 autoLiquidityAmount = _gonBalances[autoLiquidityReceiver].div(
            _gonsPerFragment
        );
        _gonBalances[address(this)] = _gonBalances[address(this)].add(
            _gonBalances[autoLiquidityReceiver]
        );
        _gonBalances[autoLiquidityReceiver] = 0;
        uint256 amountToLiquify = autoLiquidityAmount.div(2);
        uint256 amountToSwap = autoLiquidityAmount.sub(amountToLiquify);

        if (amountToSwap == 0) {
            return;
        }
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = router.WETH();

        uint256 balanceBefore = address(this).balance;

        router.swapExactTokensForETH(
            amountToSwap,
            0,
            path,
            address(this),
            block.timestamp
        );

        uint256 amountETHLiquidity = address(this).balance.sub(balanceBefore);

        if (amountToLiquify > 0 && amountETHLiquidity > 0) {
            router.addLiquidityETH{value: amountETHLiquidity}(
                address(this),
                amountToLiquify,
                0,
                0,
                autoLiquidityReceiver,
                block.timestamp
            );
        }
        _lastAddLiquidityTime = block.timestamp;
    }

    function swapBack() internal swapping {
        uint256 amountToSwap = _gonBalances[address(this)].div(
            _gonsPerFragment
        );

        if (amountToSwap == 0) {
            return;
        }

        uint256 balanceBefore = address(this).balance;
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = router.WETH();

        router.swapExactTokensForETH(
            amountToSwap,
            0,
            path,
            address(this),
            block.timestamp
        );

        uint256 amountETHToTreasuryAndRFV = address(this).balance.sub(
            balanceBefore
        );

        (bool success, ) = payable(tedRiskFreeValueReceiver).call{
            value: amountETHToTreasuryAndRFV,
            gas: 30000
        }("");
    }

    function withdrawAllToTreasury() external swapping onlyOwner {
        uint256 amountToSwap = _gonBalances[address(this)].div(
            _gonsPerFragment
        );
        require(
            amountToSwap > 0,
            "There is no TED token deposited in token contract"
        );
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = router.WETH();
        router.swapExactTokensForETH(
            amountToSwap,
            0,
            path,
            treasuryReceiver,
            block.timestamp
        );
    }

    function shouldTakeFee(address from)
        internal
        view
        returns (bool)
    {
        return !_isFeeExempt[from];
    }

    function shouldRebase() internal view returns (bool) {
        return
            _autoRebase &&
            (_totalSupply < MAX_SUPPLY) &&
            msg.sender != pair &&
            !inSwap &&
            block.timestamp >= (_lastRebasedTime + 12 minutes);
    }

    function shouldAddLiquidity() internal view returns (bool) {
        return
            _autoAddLiquidity &&
            !inSwap &&
            msg.sender != pair &&
            block.timestamp >= (_lastAddLiquidityTime + 1 days);
    }

    function shouldSwapBack() internal view returns (bool) {
        return !inSwap && msg.sender != pair;
    }

    function setAutoRebase(bool _flag) external onlyOwner {
        if (_flag) {
            _autoRebase = _flag;
            _lastRebasedTime = block.timestamp;
        } else {
            _autoRebase = _flag;
        }
    }

    function setAutoAddLiquidity(bool _flag) external onlyOwner {
        if (_flag) {
            _autoAddLiquidity = _flag;
            _lastAddLiquidityTime = block.timestamp;
        } else {
            _autoAddLiquidity = _flag;
        }
    }

    function allowance(address owner_, address spender)
        external
        view
        override
        returns (uint256)
    {
        return _allowedFragments[owner_][spender];
    }

    function decreaseAllowance(address spender, uint256 subtractedValue)
        external
        returns (bool)
    {
        uint256 oldValue = _allowedFragments[msg.sender][spender];
        if (subtractedValue >= oldValue) {
            _allowedFragments[msg.sender][spender] = 0;
        } else {
            _allowedFragments[msg.sender][spender] = oldValue.sub(
                subtractedValue
            );
        }
        emit Approval(
            msg.sender,
            spender,
            _allowedFragments[msg.sender][spender]
        );
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue)
        external
        returns (bool)
    {
        _allowedFragments[msg.sender][spender] = _allowedFragments[msg.sender][
            spender
        ].add(addedValue);
        emit Approval(
            msg.sender,
            spender,
            _allowedFragments[msg.sender][spender]
        );
        return true;
    }

    function approve(address spender, uint256 value)
        external
        override
        returns (bool)
    {
        _allowedFragments[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function checkFeeExempt(address _addr) external view returns (bool) {
        return _isFeeExempt[_addr];
    }

    function getCirculatingSupply() public view returns (uint256) {
        return
            (TOTAL_GONS.sub(_gonBalances[DEAD]).sub(_gonBalances[ZERO])).div(
                _gonsPerFragment
            );
    }

    function isNotInSwap() external view returns (bool) {
        return !inSwap;
    }

    function manualSync() external {
        IPancakeSwapPair(pair).sync();
    }

    function setFeeReceivers(
        address _autoLiquidityReceiver,
        address _treasuryReceiver,
        address _tedRiskFreeValueReceiver
    ) external onlyOwner {
        autoLiquidityReceiver = _autoLiquidityReceiver;
        treasuryReceiver = _treasuryReceiver;
        tedRiskFreeValueReceiver = _tedRiskFreeValueReceiver;
    }

    function getLiquidityBacking(uint256 accuracy)
        external
        view
        returns (uint256)
    {
        uint256 liquidityBalance = _gonBalances[pair].div(_gonsPerFragment);
        return
            accuracy.mul(liquidityBalance.mul(2)).div(getCirculatingSupply());
    }

    function setWhitelist(address _addr) external onlyOwner {
        _isFeeExempt[_addr] = true;
    }

    function setPairAddress(address _pairAddress) external onlyOwner {
        pairAddress = _pairAddress;
    }

    function setLP(address _address) external onlyOwner {
        pairContract = IPancakeSwapPair(_address);
    }

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address who) external view override returns (uint256) {
        return _gonBalances[who].div(_gonsPerFragment);
    }

    receive() external payable {}
}

