contract DARKMATTER is Context, IERC20, Ownable {

    using SafeMath for uint256;

    using Address for address;



    mapping(address => uint256) private _rOwned;

    mapping(address => uint256) private _tOwned;

    mapping(address => mapping(address => uint256)) private _allowances;



    mapping(address => bool) private _isExcludedFromFee;



    mapping(address => bool) private _isExcluded;

    address[] private _excluded;



    //antbot address list.

    mapping(address => bool) public isantiBotlisted;



    // store addresses that a automatic market maker pairs.

    mapping(address => bool) public automatedMarketMakerPairs;



    uint256 private constant MAX = ~uint256(0);

    uint256 private _tTotal = 500 * (10**6) * (10**9); //500 million tokens.

    uint256 private _rTotal = (MAX - (MAX % _tTotal));

    uint256 private _tFeeTotal;



    string private _name = "Dark Matter Metaverse";

    string private _symbol = "DMMT";

    uint8 private _decimals = 9;



    uint256 public _taxFee = 3;

    uint256 private _previousTaxFee = _taxFee;



    uint256 public _liquidityFee = 2;

    uint256 private _previousLiquidityFee = _liquidityFee;



    uint256 public _burnFee = 1;

    uint256 private _previousBurnFee = _burnFee;

    address public deadAddress = 0x000000000000000000000000000000000000dEaD;



    uint256 public _marketingFee = 2;

    uint256 private _previousmarketingFee = _marketingFee;

    address public marketingWallet = 0x5f427EFCe6fA02A86E1b239974c9574bbC1Cd7C2;



    address public BUSD;



    IUniswapV2Router02 public uniswapV2Router;

    address public uniswapV2Pair;



    bool inSwapAndLiquify;

    bool public swapAndLiquifyEnabled = true;



    uint256 public numTokensSellToAddToLiquidity = 1000000 * 10**9; //swap to liquidity when tokens in contract balance exceed this amount.



    uint256 public _minBuyTxAmount = 40 * 10**9; // min buy 40 tokens.

    uint256 public _maxSellTxAmount = 20 * (10**3) * 10**9; // max sell 20 thousand tokens.

    uint256 public maxWalletToken = _tTotal.div(2); // max wallet balance is default totalSupply/2



    event MinTokensBeforeSwapUpdated(uint256 minTokensBeforeSwap);

    event SwapAndLiquifyEnabledUpdated(bool enabled);

    event SetAutomatedMarketMakerPair(address indexed pair, bool indexed value);

    event SwapAndLiquify(

        uint256 tokensSwapped,

        uint256 ethReceived,

        uint256 tokensIntoLiqudity

    );



    modifier lockTheSwap() {

        inSwapAndLiquify = true;

        _;

        inSwapAndLiquify = false;

    }



    constructor(address PancakeSwapRouter, address busdAddress) {

        _rOwned[_msgSender()] = _rTotal;

        //testnet router: 0xD99D1c33F9fC3444f8101754aBC46c52416550D1

        //mainnet router: 0x10ED43C718714eb63d5aA57B78B54704E256024E

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(

            PancakeSwapRouter

        );

        BUSD = busdAddress;

        // Create a uniswap pair for this new token

        uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())

            .createPair(address(this), _uniswapV2Router.WETH());

        _setAutomatedMarketMakerPair(uniswapV2Pair, true);



        // set the rest of the contract variables

        uniswapV2Router = _uniswapV2Router;



        //exclude owner and this contract from fee

        _isExcludedFromFee[owner()] = true;

        _isExcludedFromFee[address(this)] = true;



        emit Transfer(address(0), _msgSender(), _tTotal);

    }



    function name() public view returns (string memory) {

        return _name;

    }



    function symbol() public view returns (string memory) {

        return _symbol;

    }



    function decimals() public view returns (uint8) {

        return _decimals;

    }



    function totalSupply() public view override returns (uint256) {

        return _tTotal;

    }



    function balanceOf(address account) public view override returns (uint256) {

        if (_isExcluded[account]) return _tOwned[account];

        return tokenFromReflection(_rOwned[account]);

    }



    function transfer(address recipient, uint256 amount)

        public

        override

        returns (bool)

    {

        _transfer(_msgSender(), recipient, amount);

        return true;

    }



    function allowance(address owner, address spender)

        public

        view

        override

        returns (uint256)

    {

        return _allowances[owner][spender];

    }



    function approve(address spender, uint256 amount)

        public

        override

        returns (bool)

    {

        _approve(_msgSender(), spender, amount);

        return true;

    }



    function transferFrom(

        address sender,

        address recipient,

        uint256 amount

    ) public override returns (bool) {

        _transfer(sender, recipient, amount);

        _approve(

            sender,

            _msgSender(),

            _allowances[sender][_msgSender()].sub(

                amount,

                "ERC20: transfer amount exceeds allowance"

            )

        );

        return true;

    }



    function increaseAllowance(address spender, uint256 addedValue)

        public

        virtual

        returns (bool)

    {

        _approve(

            _msgSender(),

            spender,

            _allowances[_msgSender()][spender].add(addedValue)

        );

        return true;

    }



    function decreaseAllowance(address spender, uint256 subtractedValue)

        public

        virtual

        returns (bool)

    {

        _approve(

            _msgSender(),

            spender,

            _allowances[_msgSender()][spender].sub(

                subtractedValue,

                "ERC20: decreased allowance below zero"

            )

        );

        return true;

    }



    function isExcludedFromReward(address account) public view returns (bool) {

        return _isExcluded[account];

    }



    function totalFees() public view returns (uint256) {

        return _tFeeTotal;

    }



    function deliver(uint256 tAmount) public {

        address sender = _msgSender();

        require(

            !_isExcluded[sender],

            "Excluded addresses cannot call this function"

        );

        (uint256 rAmount, , , , , ) = _getValues(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rTotal = _rTotal.sub(rAmount);

        _tFeeTotal = _tFeeTotal.add(tAmount);

    }



    function reflectionFromToken(uint256 tAmount, bool deductTransferFee)

        public

        view

        returns (uint256)

    {

        require(tAmount <= _tTotal, "Amount must be less than supply");

        if (!deductTransferFee) {

            (uint256 rAmount, , , , , ) = _getValues(tAmount);

            return rAmount;

        } else {

            (, uint256 rTransferAmount, , , , ) = _getValues(tAmount);

            return rTransferAmount;

        }

    }



    function tokenFromReflection(uint256 rAmount)

        public

        view

        returns (uint256)

    {

        require(

            rAmount <= _rTotal,

            "Amount must be less than total reflections"

        );

        uint256 currentRate = _getRate();

        return rAmount.div(currentRate);

    }



    function excludeFromReward(address account) public onlyOwner {

        require(!_isExcluded[account], "Account is already excluded");

        if (_rOwned[account] > 0) {

            _tOwned[account] = tokenFromReflection(_rOwned[account]);

        }

        _isExcluded[account] = true;

        _excluded.push(account);

    }



    function includeInReward(address account) external onlyOwner {

        require(_isExcluded[account], "Account is already excluded");

        for (uint256 i = 0; i < _excluded.length; i++) {

            if (_excluded[i] == account) {

                _excluded[i] = _excluded[_excluded.length - 1];

                _tOwned[account] = 0;

                _isExcluded[account] = false;

                _excluded.pop();

                break;

            }

        }

    }



    function setAutomatedMarketMakerPair(address pair, bool value)

        external

        onlyOwner

    {

        require(

            pair != uniswapV2Pair,

            "DMNT: The PancakeSwap pair cannot be removed from automatedMarketMakerPairs"

        );



        _setAutomatedMarketMakerPair(pair, value);

    }



    function _setAutomatedMarketMakerPair(address pair, bool value) private {

        require(

            automatedMarketMakerPairs[pair] != value,

            "DMNT: Automated market maker pair is already set to that value"

        );

        automatedMarketMakerPairs[pair] = value;

        emit SetAutomatedMarketMakerPair(pair, value);

    }



    function _transferBothExcluded(

        address sender,

        address recipient,

        uint256 tAmount

    ) private {

        (

            uint256 rAmount,

            uint256 rTransferAmount,

            uint256 rFee,

            uint256 tTransferAmount,

            uint256 tFee,

            uint256 tLiquidity

        ) = _getValues(tAmount);

        _tOwned[sender] = _tOwned[sender].sub(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _tOwned[recipient] = _tOwned[recipient].add(tTransferAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);

        _takeLiquidity(sender, tLiquidity);

        _reflectFee(rFee, tFee);

        emit Transfer(sender, recipient, tTransferAmount);

    }



    //to recieve ETH from uniswapV2Router when swaping

    receive() external payable {}



    function _reflectFee(uint256 rFee, uint256 tFee) private {

        _rTotal = _rTotal.sub(rFee);

        _tFeeTotal = _tFeeTotal.add(tFee);

    }



    function _getValues(uint256 tAmount)

        private

        view

        returns (

            uint256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256

        )

    {

        (

            uint256 tTransferAmount,

            uint256 tFee,

            uint256 tLiquidity

        ) = _getTValues(tAmount);

        (uint256 rAmount, uint256 rTransferAmount, uint256 rFee) = _getRValues(

            tAmount,

            tFee,

            tLiquidity,

            _getRate()

        );

        return (

            rAmount,

            rTransferAmount,

            rFee,

            tTransferAmount,

            tFee,

            tLiquidity

        );

    }



    function _getTValues(uint256 tAmount)

        private

        view

        returns (

            uint256,

            uint256,

            uint256

        )

    {

        uint256 tFee = calculateTaxFee(tAmount);

        uint256 tLiquidity = calculateLiquidityFee(tAmount);

        uint256 tTransferAmount = tAmount.sub(tFee).sub(tLiquidity);

        return (tTransferAmount, tFee, tLiquidity);

    }



    function _getRValues(

        uint256 tAmount,

        uint256 tFee,

        uint256 tLiquidity,

        uint256 currentRate

    )

        private

        pure

        returns (

            uint256,

            uint256,

            uint256

        )

    {

        uint256 rAmount = tAmount.mul(currentRate);

        uint256 rFee = tFee.mul(currentRate);

        uint256 rLiquidity = tLiquidity.mul(currentRate);

        uint256 rTransferAmount = rAmount.sub(rFee).sub(rLiquidity);

        return (rAmount, rTransferAmount, rFee);

    }



    function _getRate() private view returns (uint256) {

        (uint256 rSupply, uint256 tSupply) = _getCurrentSupply();

        return rSupply.div(tSupply);

    }



    function _getCurrentSupply() private view returns (uint256, uint256) {

        uint256 rSupply = _rTotal;

        uint256 tSupply = _tTotal;

        for (uint256 i = 0; i < _excluded.length; i++) {

            if (

                _rOwned[_excluded[i]] > rSupply ||

                _tOwned[_excluded[i]] > tSupply

            ) return (_rTotal, _tTotal);

            rSupply = rSupply.sub(_rOwned[_excluded[i]]);

            tSupply = tSupply.sub(_tOwned[_excluded[i]]);

        }

        if (rSupply < _rTotal.div(_tTotal)) return (_rTotal, _tTotal);

        return (rSupply, tSupply);

    }



    function _takeLiquidity(address sender, uint256 tLiquidity) private {

        if (_liquidityFee == 0) {

            return;

        }

        uint256 currentRate = _getRate();

        uint256 rLiquidity = tLiquidity.mul(currentRate);

        _rOwned[address(this)] = _rOwned[address(this)].add(rLiquidity);

        if (_isExcluded[address(this)])

            _tOwned[address(this)] = _tOwned[address(this)].add(tLiquidity);



        emit Transfer(sender, address(this), tLiquidity);

    }



    function calculateLiquidityFee(uint256 _amount)

        private

        view

        returns (uint256)

    {

        return _amount.mul(_liquidityFee).div(10**2);

    }



    function calculateTaxFee(uint256 _amount) private view returns (uint256) {

        return _amount.mul(_taxFee).div(10**2);

    }



    function removeAllFee() private {

        if (

            _taxFee == 0 &&

            _liquidityFee == 0 &&

            _marketingFee == 0 &&

            _burnFee == 0

        ) return;



        _previousTaxFee = _taxFee;

        _previousLiquidityFee = _liquidityFee;

        _previousBurnFee = _burnFee;

        _previousmarketingFee = _marketingFee;



        _taxFee = 0;

        _liquidityFee = 0;

        _marketingFee = 0;

        _burnFee = 0;

    }



    function restoreAllFee() private {

        _taxFee = _previousTaxFee;

        _liquidityFee = _previousLiquidityFee;

        _burnFee = _previousBurnFee;

        _marketingFee = _previousmarketingFee;

    }



    function isExcludedFromFee(address account) public view returns (bool) {

        return _isExcludedFromFee[account];

    }



    function _approve(

        address owner,

        address spender,

        uint256 amount

    ) private {

        require(owner != address(0), "ERC20: approve from the zero address");

        require(spender != address(0), "ERC20: approve to the zero address");



        _allowances[owner][spender] = amount;

        emit Approval(owner, spender, amount);

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) private {

        require(from != address(0), "ERC20: transfer from the zero address");

        require(amount > 0, "Transfer amount must be greater than zero");

        require(

            !isantiBotlisted[from] && !isantiBotlisted[to],

            "antiBotlisted address"

        );



        bool excludedAccount = _isExcludedFromFee[from] ||

            _isExcludedFromFee[to];



        if (automatedMarketMakerPairs[from] && !excludedAccount) {

            require(

                amount >= _minBuyTxAmount,

                "Buy transfer amount must exceeds the minBuyTxAmount."

            );



            uint256 contractBalanceRecepient = balanceOf(to);

            require(

                contractBalanceRecepient + amount <= maxWalletToken,

                "Exceeds maximum wallet token amount."

            );

        } else if (automatedMarketMakerPairs[to] && !excludedAccount) {

            require(

                amount <= _maxSellTxAmount,

                "Sell transfer amount exceeds the maxSellTransactionAmount."

            );

            checkForCoolDown(from, to);

        }



        uint256 contractTokenBalance = balanceOf(address(this));

        bool overMinTokenBalance = contractTokenBalance >=

            numTokensSellToAddToLiquidity;

        if (

            overMinTokenBalance &&

            !inSwapAndLiquify &&

            from != uniswapV2Pair &&

            swapAndLiquifyEnabled

        ) {

            contractTokenBalance = numTokensSellToAddToLiquidity;

            //add liquidity and send busd to marketing address

            swapAndLiquify(contractTokenBalance);

        }



        //indicates if fee should be deducted from transfer

        bool takeFee = true;



        //check if transfer is a trade.

        bool isTrade = automatedMarketMakerPairs[to] ||

            automatedMarketMakerPairs[from];



        //if any account belongs to _isExcludedFromFee account or is not a trade then remove the fee

        if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || !isTrade) {

            takeFee = false;

        }



        _tokenTransfer(from, to, amount, takeFee);

    }



    function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {

        // combine the Liquidity and marketing fees

        uint256 combineFees = _liquidityFee.add(_marketingFee); // marketing + liquidity fees

        uint256 tokensForLiquidity = contractTokenBalance

            .mul(_liquidityFee)

            .div(combineFees);



        uint256 tokensForMarketing = contractTokenBalance.sub(

            tokensForLiquidity

        );

        swapTokensForBUSD(tokensForMarketing);



        // split the Liquidity tokens balance into halves

        uint256 half = tokensForLiquidity.div(2);

        uint256 otherHalf = tokensForLiquidity.sub(half);



        // capture the contract's current ETH balance.

        // this is so that we can capture exactly the amount of ETH that the

        // swap creates, and not make the liquidity event include any ETH that

        // has been manually sent to the contract

        uint256 initialBalance = address(this).balance;



        // swap tokens for ETH

        swapTokensForEth(half); // <- this breaks the ETH -> HATE swap when swap+liquify is triggered



        // how much ETH did we just swap into?

        uint256 newBalance = address(this).balance.sub(initialBalance);



        // add liquidity to uniswap

        addLiquidity(otherHalf, newBalance);



        emit SwapAndLiquify(half, newBalance, otherHalf);

    }



    function swapTokensForBUSD(uint256 tokenAmount) private {

        address[] memory path = new address[](3);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();

        path[2] = BUSD; // BUSD cotract address



        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // make the swap

        uniswapV2Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(

            tokenAmount,

            0,

            path,

            marketingWallet,

            block.timestamp

        );

    }



    function swapTokensForEth(uint256 tokenAmount) private {

        // generate the uniswap pair path of token -> weth

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();



        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // make the swap

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0, // accept any amount of ETH

            path,

            address(this),

            block.timestamp

        );

    }



    function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {

        // approve token transfer to cover all possible scenarios

        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // add the liquidity

        uniswapV2Router.addLiquidityETH{value: ethAmount}(

            address(this),

            tokenAmount,

            0, // slippage is unavoidable

            0, // slippage is unavoidable

            owner(),

            block.timestamp

        );

    }



    //this method is responsible for taking all fee, if takeFee is true

    function _tokenTransfer(

        address sender,

        address recipient,

        uint256 amount,

        bool takeFee

    ) private {

        if (!takeFee) {

            removeAllFee();

        }



        if (_isExcluded[sender] && !_isExcluded[recipient]) {

            _transferFromExcluded(sender, recipient, amount);

        } else if (!_isExcluded[sender] && _isExcluded[recipient]) {

            _transferToExcluded(sender, recipient, amount);

        } else if (!_isExcluded[sender] && !_isExcluded[recipient]) {

            _transferStandard(sender, recipient, amount);

        } else if (_isExcluded[sender] && _isExcluded[recipient]) {

            _transferBothExcluded(sender, recipient, amount);

        } else {

            _transferStandard(sender, recipient, amount);

        }



        if (!takeFee) {

            restoreAllFee();

        }

    }



    function _transferStandard(

        address sender,

        address recipient,

        uint256 tAmount

    ) private {

        (

            uint256 rAmount,

            uint256 rTransferAmount,

            uint256 rFee,

            uint256 tTransferAmount,

            uint256 tFee,

            uint256 tLiquidity

        ) = _getValues(tAmount);

        (tTransferAmount, rTransferAmount) = takeBurn(

            sender,

            tTransferAmount,

            rTransferAmount,

            tAmount

        );

        (tTransferAmount, rTransferAmount) = takeMarketing(

            sender,

            tTransferAmount,

            rTransferAmount,

            tAmount

        );

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);

        _takeLiquidity(sender, tLiquidity);

        _reflectFee(rFee, tFee);

        emit Transfer(sender, recipient, tTransferAmount);

    }



    function takeMarketing(

        address sender,

        uint256 tTransferAmount,

        uint256 rTransferAmount,

        uint256 tAmount

    ) private returns (uint256, uint256) {

        if (_marketingFee == 0) {

            return (tTransferAmount, rTransferAmount);

        }

        uint256 tMarketing = tAmount.div(100).mul(_marketingFee);

        uint256 rMarketing = tMarketing.mul(_getRate());

        rTransferAmount = rTransferAmount.sub(rMarketing);

        tTransferAmount = tTransferAmount.sub(tMarketing);

        _rOwned[address(this)] = _rOwned[address(this)].add(rMarketing);

        emit Transfer(sender, address(this), tMarketing);

        return (tTransferAmount, rTransferAmount);

    }



    function takeBurn(

        address sender,

        uint256 tTransferAmount,

        uint256 rTransferAmount,

        uint256 tAmount

    ) private returns (uint256, uint256) {

        if (_burnFee == 0) {

            return (tTransferAmount, rTransferAmount);

        }

        uint256 tBurn = tAmount.div(100).mul(_burnFee);

        uint256 rBurn = tBurn.mul(_getRate());

        rTransferAmount = rTransferAmount.sub(rBurn);

        tTransferAmount = tTransferAmount.sub(tBurn);

        _rOwned[deadAddress] = _rOwned[deadAddress].add(rBurn);

        emit Transfer(sender, deadAddress, tBurn);

        return (tTransferAmount, rTransferAmount);

    }



    function _transferToExcluded(

        address sender,

        address recipient,

        uint256 tAmount

    ) private {

        (

            uint256 rAmount,

            uint256 rTransferAmount,

            uint256 rFee,

            uint256 tTransferAmount,

            uint256 tFee,

            uint256 tLiquidity

        ) = _getValues(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _tOwned[recipient] = _tOwned[recipient].add(tTransferAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);

        _takeLiquidity(sender, tLiquidity);

        _reflectFee(rFee, tFee);

        emit Transfer(sender, recipient, tTransferAmount);

    }



    function _transferFromExcluded(

        address sender,

        address recipient,

        uint256 tAmount

    ) private {

        (

            uint256 rAmount,

            uint256 rTransferAmount,

            uint256 rFee,

            uint256 tTransferAmount,

            uint256 tFee,

            uint256 tLiquidity

        ) = _getValues(tAmount);

        _tOwned[sender] = _tOwned[sender].sub(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);

        _takeLiquidity(sender, tLiquidity);

        _reflectFee(rFee, tFee);

        emit Transfer(sender, recipient, tTransferAmount);

    }



    function excludeFromFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = true;

    }



    function includeInFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = false;

    }



    function setMarketingWallet(address newWallet) external onlyOwner {

        marketingWallet = newWallet;

    }



    function setFees(

        uint256 taxFee,

        uint256 liquidityFee,

        uint256 marketingFee,

        uint256 burnFee

    ) external onlyOwner {

        _taxFee = taxFee;

        _liquidityFee = liquidityFee;

        _marketingFee = marketingFee;

        _burnFee = burnFee;

    }



    function antiBotlistAddress(address account, bool value)

        external

        onlyOwner

    {

        isantiBotlisted[account] = value;

    }



    function setNumTokensSellToAddToLiquidity(uint256 newAmt)

        external

        onlyOwner

    {

        numTokensSellToAddToLiquidity = newAmt * (10**9);

    }



    function setMaxWalletAmount(uint256 maxWalletToken_) external onlyOwner {

        require(maxWalletToken_ > 0, "Cannot set transaction amount as zero");

        maxWalletToken = maxWalletToken_ * (10**9);

    }



    function setMinBuyTxAmount(uint256 minBuyTxAmount) external onlyOwner {

        require(

            minBuyTxAmount > 0,

            "transaction amount must be greater than zero"

        );

        _minBuyTxAmount = minBuyTxAmount * (10**9);

    }



    function setMaxSellTxAmount(uint256 maxSellTxAmount) external onlyOwner {

        require(

            maxSellTxAmount > 0,

            "transaction amount must be greater than zero"

        );

        _maxSellTxAmount = maxSellTxAmount * (10**9);

    }



    function setSwapAndLiquifyEnabled(bool _enabled) public onlyOwner {

        swapAndLiquifyEnabled = _enabled;

        emit SwapAndLiquifyEnabledUpdated(_enabled);

    }



    //////////----COOL DOWN --- /////



    mapping(address => uint256) private lastTxnTimeStamp;

    bool public cooldownEnabled = true;

    uint256 public sellCooldownperiod = 3600;



    event CoolDownPeriodUpdated(

        address indexed operator,

        uint256 newCoolDownPeriod

    );



    function enableCooldown(bool value) external onlyOwner {

        require(value != cooldownEnabled, "CooldownEnabled is already set.");

        cooldownEnabled = value;

    }



    function checkForCoolDown(address from, address to) public {

        if (cooldownEnabled && automatedMarketMakerPairs[to]) {

            uint256 coolDownTimestamp = lastTxnTimeStamp[from].add(

                sellCooldownperiod

            );



            require(

                coolDownTimestamp < block.timestamp,

                "Wait till one hour Cool Down Pd"

            );



            lastTxnTimeStamp[from] = block.timestamp;

        }

    }



    function setSellCooldownperiod(uint256 _seconds) external onlyOwner {

        sellCooldownperiod = _seconds;

    }

}

