pragma solidity  = 0.8.13;





contract HuskyInu is ERC20 {

    using SafeMath for uint256;

    using Address for address;

    uint256 public maxSupply = 10**10 * 10**18;

    IUniswapV2Router02 public uniswapV2Router;

    address public uniswapV2Pair;

    uint256 public rewardSellFee = 2; // Reward Sell Fee

    uint256 public marketingSellFee = 2; // Marketing Sell Fee

    uint256 public rewardBuyFee = 2; // Reward Buy Fee

    uint256 public marketingBuyFee = 2; // Marketing Buy Fee

    uint256 public liquidityFee = 2;

    uint256 public burnFee = 2;    

    uint256 public maxBuy = 0;

    uint256 public minBuy = 0;

    uint256 public maxSell = 0;

    uint256 public minSell = 0;

    address public marketingAddress = 0xB436c1E09F20412ca1E53252dBF62120197F17F4; // Marketing Wallet

    address public rewardAddress = 0xc1D3794Dec5eA6a883648767f8657A5Ed12cB1E9; // Reward WalletWallet

    bool public preventBotContract = false;

    bool public limitSell = false;

    bool public limitBuy = false;

    bool public taxStatus = false;

    mapping(address => bool) public excludeFee;

    mapping(address => bool) public blacklist;



    constructor(string memory _name, string memory _symbol) ERC20(_name, _symbol , maxSupply) {

        uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this), uniswapV2Router.WETH());

        _approve(address(this), address(uniswapV2Router), ~uint256(0));

    }



    function setLimitSell(bool enable, uint256 _max, uint256 _min) external onlyOwner {

        limitSell = enable;

        maxSell = _max;

        minSell = _min;

    }



    function setLimitBuy(bool enable, uint256 _max, uint256 _min) external onlyOwner {

        limitBuy = enable;

        maxBuy = _max;

        minBuy = _min;

    }



    function setPreventBot(bool enable) external onlyOwner {

        preventBotContract = enable;

    }



    function setTax(bool enable) external onlyOwner {

        taxStatus = enable;

    }



    function addBlacklist(address b, bool enable) external onlyOwner {

        blacklist[b] = enable;

    }



    function addExcludeFee(address b, bool enable) external onlyOwner {

        excludeFee[b] = enable;

    }



    function _transfer( address sender, address recipient, uint256 amount ) internal virtual override {

        if(preventBotContract == true && // Blacklist Contract that try to sell tokens

            recipient == uniswapV2Pair &&

            sender != address(this)){

                if(sender.isContract() == true){

                    blacklist[sender] = true;

                }

        }

        require(!blacklist[sender] && !blacklist[recipient], "BLACKLISTED");

        if(preventBotContract == true && // Blacklist Contract that try to scam tokens

            sender == uniswapV2Pair &&

            recipient != address(this)){

                if(recipient.isContract() == true){

                    blacklist[recipient] = true;

                }

        }



        bool allowToTransfer = true;

        if(recipient == uniswapV2Pair && // Swap Tokens to BNB (SELL)

            sender != address(this) &&

            sender != owner() &&

            !excludeFee[sender]){

            bool allowToSell = true;



            if(limitSell == true) {

                if(amount < minSell*10**18 || amount > maxSell*10**18) {

                    allowToSell = false;

                }

            }



            if(allowToSell == true) {

                if(taxStatus == true){ 

                    uint256 _RewardFee = amount.mul(rewardSellFee).div(100);

                    uint256 _MarketingFee = amount.mul(marketingSellFee).div(100);

                    uint256 _LiquidityFee = amount.mul(liquidityFee).div(100);

                    uint256 _BurnFee = amount.mul(burnFee).div(100);



                    super._transfer(sender, rewardAddress, _RewardFee);

                    super._transfer(sender, marketingAddress, _MarketingFee);

                    super._transfer(sender, uniswapV2Pair, _LiquidityFee);

                    super._burn(sender, _BurnFee);



                    amount = amount.sub(_RewardFee.add(_MarketingFee).add(_BurnFee).add(_LiquidityFee));

                }

            }

            else {

                allowToTransfer = false;

            }

        }



        if(sender == uniswapV2Pair && // Swap BNB to Tokens (BUY)

            recipient != owner() &&

            !excludeFee[recipient]){



            if(limitBuy == true) {

                if(amount < minBuy*10**18 || amount > maxBuy*10**18) {

                    allowToTransfer = false;

                }

            }



            if(allowToTransfer == true) {

                if(taxStatus == true) {

                    uint256 _RewardFee = amount.mul(rewardBuyFee).div(100);

                    uint256 _MarketingFee = amount.mul(marketingBuyFee).div(100);



                    super._transfer(sender, rewardAddress, _RewardFee);

                    super._transfer(sender, marketingAddress, _MarketingFee);



                    amount = amount.sub(_RewardFee.add(_MarketingFee));

                }

            }

        }



        require(allowToTransfer == true, "Not Allow to Transfer");

        super._transfer(sender, recipient, amount);

    }

}

