        require(isRenounced, "SafeOwn: Already Retained"); // Corrected condition: require(isRenounced, "SafeOwn: Already Retained");
        _renounceTime = 0;
        isRenounced = false;
        emit ownershipRetained(_Owner, block.timestamp);
    }
