contract BabyKabosuInu is Context, IERC20, Ownable {

    using SafeMath for uint256;

    using Address for address;



    string private _name = "BabyKabosuInu";

    string private _symbol = "BKI";

    uint8 private _decimals = 9;



    mapping(address => uint256) internal _reflectionBalance;

    mapping(address => uint256) internal _balanceLimit;

    mapping(address => uint256) internal _tokenBalance;



    mapping (address => bool) public _blackList;

    mapping (address => bool) public _maxAmount;

    mapping (address => bool) public _maxWallet;

    mapping(address => mapping(address => uint256)) internal _allowances;





    uint256 private constant MAX = ~uint256(0);

    uint256 internal _tokenTotal = 100_000_000_000_000e9;

    uint256 internal _reflectionTotal = (MAX - (MAX % _tokenTotal));



    mapping(address => bool) isTaxless;

    mapping(address => bool) internal _isExcluded;

    address[] internal _excluded;



    uint256 public _feeDecimal = 2;

    uint256 public _taxFee = 100; // means 2% which distribute to all holders reflection fee

    uint256 public _marketingFee=300;// meanse 2%  

    uint256 public _liquidityFee = 100; // means 2%

    uint256 public _rewardFee = 300; // means 4%

    uint256 public _ecosystemFee = 200; // means 5%



    uint256 public _SelltaxFee = 200; // means 2% which distribute to all holders reflection fee

    uint256 public _SellmarketingFee = 600;// meanse 7% 

    uint256 public _SelllLiquidityFee = 200; // means 2%

    uint256 public _SellrewardFee = 600; // means 6%

    uint256 public _SellecosystemFee = 400; // means 7%





    address private marketingAddress=0x6d1ffD31752CBb3BbEbe27CA064c599904D6DD27;

    address private rewardAddress=0xEdAa6c5F152F6557cf2f097475271D5Bd481da02;

    address private ecosystemAddress=0xB1BB562B49754761fB3e542A758b880cc4Ab5Ba7;





    uint256 public _taxFeeTotal;

    uint256 public _liquidityFeeTotal;



    bool public isFeeActive = true; // should be true

    bool private inSwapAndLiquify;

    bool public swapAndLiquifyEnabled = true;

    bool private tradingEnable = true;



    uint256 public minTokensBeforeSwap = 100_00_000e18;

    IUniswapV2Router02 public  uniswapV2Router;

    address public  uniswapV2Pair;



    event SwapAndLiquifyEnabledUpdated(bool enabled);

    event SwapAndLiquify(uint256 tokensSwapped,uint256 ethReceived, uint256 tokensIntoLiqudity);



    modifier lockTheSwap {

        inSwapAndLiquify = true;

        _;

        inSwapAndLiquify = false;

    }



    constructor()  {

         IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E); // for BSC Pncake v2

        // IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x1b02dA8Cb0d097eB8D57A175b88c7D8b47997506); // for SushiSwap

        // IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D); // for Ethereum uniswap v2

        uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())

            .createPair(address(this), _uniswapV2Router.WETH());

        uniswapV2Router = _uniswapV2Router;



        isTaxless[owner()] = true;

        isTaxless[address(this)] = true;





        // exlcude pair address from tax rewards

        _isExcluded[address(uniswapV2Pair)] = true;

        _excluded.push(address(uniswapV2Pair));



        _reflectionBalance[owner()] = _reflectionTotal;

        emit Transfer(address(0),owner(), _tokenTotal);

    }



    function name() public view returns (string memory) {

        return _name;

    }



    function symbol() public view returns (string memory) {

        return _symbol;

    }



    function decimals() public view returns (uint8) {

        return _decimals;

    }



    function totalSupply() public override view returns (uint256) {

        return _tokenTotal;

    }



    function balanceOf(address account) public override view returns (uint256) {

        if (_isExcluded[account]) return _tokenBalance[account];

        return tokenFromReflection(_reflectionBalance[account]);

    }



    function transfer(address recipient, uint256 amount)

        public

        override

        virtual

        returns (bool)

    {

       _transfer(_msgSender(),recipient,amount);

        return true;

    }



    function allowance(address owner, address spender)

        public

        override

        view

        returns (uint256)

    {

        return _allowances[owner][spender];

    }



    function approve(address spender, uint256 amount)

        public

        override

        returns (bool)

    {

        _approve(_msgSender(), spender, amount);

        return true;

    }



    function transferFrom(

        address sender,

        address recipient,

        uint256 amount

    ) public override virtual returns (bool) {

        _transfer(sender,recipient,amount);



        _approve(sender,_msgSender(),_allowances[sender][_msgSender()].sub( amount,"ERC20: transfer amount exceeds allowance"));

        return true;

    }





    function increaseAllowance(address spender, uint256 addedValue)

        public

        virtual

        returns (bool)

    {

        _approve(

            _msgSender(),

            spender,

            _allowances[_msgSender()][spender].add(addedValue)

        );

        return true;

    }



    function decreaseAllowance(address spender, uint256 subtractedValue)

        public

        virtual

        returns (bool)

    {

        _approve(

            _msgSender(),

            spender,

            _allowances[_msgSender()][spender].sub(

                subtractedValue,

                "ERC20: decreased allowance below zero"

            )

        );

        return true;

    }



    function isExcluded(address account) public view returns (bool) {

        return _isExcluded[account];

    }



    function reflectionFromToken(uint256 tokenAmount, bool deductTransferFee)

        public

        view

        returns (uint256)

    {

        require(tokenAmount <= _tokenTotal, "Amount must be less than supply");

        if (!deductTransferFee) {

            return tokenAmount.mul(_getReflectionRate());

        } else {

            return

                tokenAmount.sub(tokenAmount.mul(_taxFee).div(10** _feeDecimal + 2)).mul(

                    _getReflectionRate()

                );

        }

    }



    function tokenFromReflection(uint256 reflectionAmount)

        public

        view

        returns (uint256)

    {

        require(

            reflectionAmount <= _reflectionTotal,

            "Amount must be less than total reflections"

        );

        uint256 currentRate = _getReflectionRate();

        return reflectionAmount.div(currentRate);

    }



    function excludeAccount(address account) external onlyOwner() {

        require(

            account != address(uniswapV2Router),

            "ERC20: We can not exclude Uniswap router."

        );

        require(!_isExcluded[account], "ERC20: Account is already excluded");

        if (_reflectionBalance[account] > 0) {

            _tokenBalance[account] = tokenFromReflection(

                _reflectionBalance[account]

            );

        }

        _isExcluded[account] = true;

        _excluded.push(account);

    }



    function includeAccount(address account) external onlyOwner() {

        require(_isExcluded[account], "ERC20: Account is already included");

        for (uint256 i = 0; i < _excluded.length; i++) {

            if (_excluded[i] == account) {

                _excluded[i] = _excluded[_excluded.length - 1];

                _tokenBalance[account] = 0;

                _isExcluded[account] = false;

                _excluded.pop();

                break;

            }

        }

    }



    function _approve(

        address owner,

        address spender,

        uint256 amount

    ) private {

        require(owner != address(0), "ERC20: approve from the zero address");

        require(spender != address(0), "ERC20: approve to the zero address");



        _allowances[owner][spender] = amount;

        emit Approval(owner, spender, amount);

    }



    function _transfer(

        address sender,

        address recipient,

        uint256 amount

    ) private {

        require(sender != address(0), "ERC20: transfer from the zero address");

        require(amount > 0, "Transfer amount must be greater than zero");

        require(tradingEnable,"trading is disable");



        uint256 transferAmount = amount;

        uint256 rate = _getReflectionRate();



        uint256 constractBal=balanceOf(address(this));

        bool overMinTokenBalance = constractBal >= minTokensBeforeSwap;



        if(!inSwapAndLiquify && overMinTokenBalance && 

        recipient == uniswapV2Pair 

