    function updateGasForProcessing(uint256 newValue) public onlyOwner {
        require(newValue >= 200000 && newValue <= 500000, "INCOME: gasForProcessing must be between 200,000 and 500,000");
        require(newValue != gasForProcessing, "INCOME: Cannot update gasForProcessing to same value");
        emit GasForProcessingUpdated(newValue, gasForProcessing);
