        uint256 jackpotFee

    ) external onlyAuthorized {

        require(

            liquidityFee.add(marketingFee).add(devFee).add(jackpotFee) <=

                TOTAL_FEES_LIMIT,

            "Total fees can not exceed the declared limit"

        );

        sLiquidityFee = liquidityFee;

        sMarketingFee = marketingFee;

        sDevFee = devFee;

        sJackpotFee = jackpotFee;



