            .div(MAX_PCT);

        uint256 tokens = _jackpotTokens

            .mul(jackpotCashout)

            .div(MAX_PCT)

            .mul(MAX_PCT.sub(jackpotBuyerShare))

            .div(MAX_PCT);



        return (bnb, tokens);

    }



