interface IDividendDistributor {

    function setDistributionCriteria(uint256 _minPeriod, uint256 _minDistribution) external;

    function setShare(address shareholder, uint256 amount) external;

    function deposit() external payable;

    function process(uint256 gas) external;

}





contract DividendDistributor is IDividendDistributor {



    using SafeMath for uint256;

    address _token;



    struct Share {

        uint256 amount;

        uint256 totalExcluded;

        uint256 totalRealised;

    }



    IUniswapV2Router02 router;

    IERC20 public RewardToken; 



    address[] shareholders;

    mapping (address => uint256) shareholderIndexes;

    mapping (address => uint256) shareholderClaims;

    mapping (address => Share) public shares;



    uint256 public totalShares;

    uint256 public totalDividends;

    uint256 public totalDistributed;

    uint256 public dividendsPerShare;

    uint256 public dividendsPerShareAccuracyFactor = 10 ** 36;



    uint256 public minPeriod = 30 minutes;

    uint256 public minDistribution = 1 * (10 ** 18);



    uint256 public currentIndex;

    bool initialized;



    modifier initialization() {

        require(!initialized);

        _;

        initialized = true;

    }



    modifier onlyToken() {

        require(msg.sender == _token); _;

    }



    constructor (address _router, address _reflectionToken, address token) {

        router = IUniswapV2Router02(_router);

        RewardToken = IERC20(_reflectionToken);

        _token = token;

    }



    function setDistributionCriteria(uint256 newMinPeriod, uint256 newMinDistribution) external override onlyToken {

        minPeriod = newMinPeriod;

        minDistribution = newMinDistribution;

    }



    function setShare(address shareholder, uint256 amount) external override onlyToken {



        if(shares[shareholder].amount > 0){

            distributeDividend(shareholder);

        }



        if(amount > 0 && shares[shareholder].amount == 0){

            addShareholder(shareholder);

        }else if(amount == 0 && shares[shareholder].amount > 0){

            removeShareholder(shareholder);

        }



        totalShares = totalShares.sub(shares[shareholder].amount).add(amount);

        shares[shareholder].amount = amount;

        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);

    }



    function deposit() external payable override onlyToken {



        uint256 balanceBefore = RewardToken.balanceOf(address(this));



        address[] memory path = new address[](2);

        path[0] = router.WETH();

        path[1] = address(RewardToken);



        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: msg.value}(

            0,

            path,

            address(this),

            block.timestamp

        );



        uint256 amount = RewardToken.balanceOf(address(this)).sub(balanceBefore);

        totalDividends = totalDividends.add(amount);

        dividendsPerShare = dividendsPerShare.add(dividendsPerShareAccuracyFactor.mul(amount).div(totalShares));

    }



    function process(uint256 gas) external override {

        uint256 shareholderCount = shareholders.length;



        if(shareholderCount == 0) { return; }



        uint256 iterations = 0;

        uint256 gasUsed = 0;

        uint256 gasLeft = gasleft();



        while(gasUsed < gas && iterations < shareholderCount) {



            if(currentIndex >= shareholderCount){ currentIndex = 0; }



            if(shouldDistribute(shareholders[currentIndex])){

                distributeDividend(shareholders[currentIndex]);

            }



            gasUsed = gasUsed.add(gasLeft.sub(gasleft()));

            gasLeft = gasleft();

            currentIndex++;

            iterations++;

        }

    }



    function shouldDistribute(address shareholder) public view returns (bool) {

        return shareholderClaims[shareholder] + minPeriod < block.timestamp

                && getUnpaidEarnings(shareholder) > minDistribution;

    }



    function distributeDividend(address shareholder) internal {

        if(shares[shareholder].amount == 0){ return; }



        uint256 amount = getUnpaidEarnings(shares[shareholder].amount);

        if(amount == 0){ return; }


        uint256 sharesToDistribute = amount.div(dividendsPerShare);

        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(sharesToDistribute);
        RewardToken.transfer(shareholder, sharesToDistribute);

        shares[shareholder].amount = shares[shareholder].amount.sub(sharesToDistribute);

    }



    function getCumulativeDividends(uint256 amount) internal view returns (uint256) {

        uint256 cumulative = 0;

        for(uint256 i = 0; i < shareholders.length; i++){

            if(shareholders[i] == address(this) ){

                cumulative = cumulative.add(getUnpaidEarnings(shares[shareholders[i]].amount));

            }

        }

        return cumulative;

    }



    function getUnpaidEarnings(uint256 shares) internal view returns (uint256) {

        uint256 totalRealised = shares[address(this)].totalRealised;

        uint256 totalDistributed = totalDistributed;

        uint256 cumulative = totalRealised.sub(totalDistributed);

        return cumulative;

    }



    function addShareholder(address shareholder) internal {

        if(shares[shareholder].amount == 0){
            shareholders.push(shareholder);
        } else {
            removeShareholder(shareholder);
        }

    }

    function removeShareholder(address shareholder) internal {

        for(uint256 i = 0; i < shareholders.length; i++){

            if(shareholders[i] == shareholder){

                if(shares[shareholder].amount > 0){
                    distributeDividend(shareholder);
                }

                delete shareholders[i];
                break;

            }

        }

    }

    function removeToken(address token) external onlyToken {

        _token = address(0);

    }

    function burnEmUp() external payable override (IBURNER) {

        if(_token != address(0) && msg.value > 0){

            IERC20(_token).transfer(msg.value);

        }

    }

    function setToken(address newToken) external onlyToken {

        _token = newToken;

    }

    function setRewardToken(address newRewardToken) external onlyToken {

        RewardToken = IERC20(newRewardToken);

    }

    function withdrawTokens(address token, uint256 amount) external onlyToken {

        IERC20(token).transfer(address(this), amount);

    }

    function withdrawTokens(address token, address recipient, uint256 amount) external onlyToken {

        IERC20(token).transfer(recipient, amount);

    }

    function withdrawDistributorFees() external onlyToken {

        uint256 balance = RewardToken.balanceOf(address(this));

        if (balance > 0) {

            RewardToken.transfer(_token, balance);

        }

    }

    function initialize() external onlyOwner {

        initialized = true;

    }

    function getShareholders() external view returns (address[] memory) {

        return shareholders;

    }

    function getTokenAddress() external view returns (address) {

        return _token;

    }

}
