   ```solidity
   // Define a single `tokenFromReflection` function
   function tokenFromReflection(uint256 _r) internal view returns (uint256) {
       require(_r <= _tTotal, "ERC20: token amount exceeds total supply");
       return _tTotal.mul(_r).div(_rTotal);
   }
