contract CitysHome is ERC20, Ownable {



    address public presaleAddress = 0xe054f942D773Ee44Ad364b723F6544fE875f5b76;



    address public liquidityAddress = 0x59C85B9bCD798a69766dDc28ceF5970F837B7b72;



    address public airdropAddress = 0x3202118d28349059257b66f2FB43B6d4cb9F74E2;



    address public teamAddress = 0xF7B10a5EE828dE6314afa451523B4D52436fcf2D;



    address public marketingAddress = 0xF1aF804bF8B18230C1C12f85c5e891a88B71b738;



    address public deadWallet = 0x000000000000000000000000000000000000dEaD;



    address public swapAddress;



    uint256 liquidityFee = 3;



    uint256 burnFee = 2;



    uint256 public PVP = 17500000 * 10 ** 18;



    uint256 public agriculture = 7500000 * 10 ** 18;



    mapping (address => uint256) public lockEndTime;



    constructor() ERC20("CitysHome", "CHC") {



        _mint(address(this),25000000 * 10 ** 18);



        _mint(presaleAddress,12500000 * 10 ** 18);



        _mint(liquidityAddress,7500000 * 10 ** 18);



        _mint(airdropAddress,2000000 * 10 ** 18);



        _mint(teamAddress,1500000 * 10 ** 18);  



        _mint(marketingAddress,1500000 * 10 ** 18);



        lockEndTime[airdropAddress] = block.timestamp + 30 days;



        lockEndTime[teamAddress] = block.timestamp + 365 days;

    }



    function setSwapAddress(address swapAddr) public onlyOwner {

        swapAddress = swapAddr;

    }



    function setBurnFee(uint256 fee) public onlyOwner {

        burnFee = fee;

    }



    function setSwapFee(uint256 fee) public onlyOwner {

        liquidityFee = fee;

    }



    function ownerWithdrew(uint256 amount) public onlyOwner {



        amount = amount * 10 **18;



        uint256 dexBalance = balanceOf(address(this));



        require(amount > 0, "You need to send some token");



        require(amount <= dexBalance, "Not enough tokens in the reserve");



        _transfer(address(this), msg.sender, amount);

    }



    function ownerDeposit(uint256 amount) public onlyOwner {



        amount = amount * 10 **18;



        uint256 dexBalance = balanceOf(msg.sender);



        require(amount > 0, "You need to send some token");



        require(amount <= dexBalance, "Dont hava enough token");



        _transfer(msg.sender, address(this), amount);

    }



    function _transfer(

        address sender,

        address recipient,

        uint256 amount

    ) internal override {

        require(sender != address(0), "ERC20: transfer from the zero address");

        require(recipient != address(0), "ERC20: transfer to the zero address");



        if(amount == 0) {

            return super._transfer(sender, recipient, 0);

        }



        if(sender == airdropAddress || sender == teamAddress){

            require(block.timestamp > lockEndTime[sender], "ERC20: Lock time is not over");

        }



        if(sender == liquidityAddress || recipient == liquidityAddress){

            return super._transfer(sender, recipient, amount);

        }



        if(sender == swapAddress){



            uint256 burnFees = amount * burnFee / 100;



            uint256 liquidityFees = amount * liquidityFee / 100;



            super._transfer(sender, recipient, amount);



            super._transfer(recipient, deadWallet, burnFees);



            super._transfer(recipient, swapAddress, liquidityFees);



            return;

        }



        if(recipient == swapAddress){



            uint256 burnFees = amount * burnFee / 100;



            uint256 liquidityFees = amount * liquidityFee / 100;



            amount = amount - burnFees - liquidityFees;



            super._transfer(sender, recipient, amount);



            super._transfer(sender, deadWallet, burnFees);



            super._transfer(sender, liquidityAddress, liquidityFees);



            return;

        }



        return super._transfer(sender, recipient, amount);

    }





}

