        swapTokensForEth(totalSwapTokens);

        uint256 newBalance = address(this).balance;

        addLiquidity(liquidityTokens, newBalance);

        uint256 bnbTomarketing = newBalance * marketingFee / ((liquidityFee/2) + marketingFee + rewardFees);

