        _isExcludedFromFees[address(this)] = true;



        // Set up the pancakeswap V2 router

        IUniswapV2Router02 pancakeswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

