// File: contracts/KINGBONK.sol


pragma solidity ^0.8.17;








contract NINJATURTLES is ERC20, ERC20Burnable, Ownable, AccessControl, ERC20Permit {

    using SafeMath for uint;
    using SafeERC20 for IERC20;

    uint256 public constant DENOMINATOR=10000;
    bytes32 public constant MANAGEMENT_ROLE = keccak256("MANAGEMENT_ROLE");

    address constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address constant ZERO = 0x0000000000000000000000000000000000000000;

    uint256 public maxSupply = 200000000000 * 10**18;

    address managerWallet = 0x2f7DF8b485b3C9AE722E87e0c0b47d02D0b60436;
    address marketingWallet = 0x7b9f4f2e4fc67DD8B2FC17E1C1F7C13fD0C3DA9b;

    // Settings of Auto Swapping the tokens which are collected from taxes
    DividendDistributor public distributor;
    IPancakeSwapV2Router02 public PancakeSwapV2Router;
    address public PancakeSwapV2Pair;
    address public WETH;

    uint96 distributorGas = 500000;
    uint48 public launchTime;

    bool initialized = false;
    bool tradingEnabled = false;
    bool inSwap = false;
    bool public autoSwap = true;
    bool public sniperTaxEnabled = true;

    uint32 public transferGas = 1000;
    uint32 public buyTax = 1000;
    uint32 public sellTax = 1000;
    uint32 public transferTax = 1000;
    uint32 public liquidityShare = 2000;
    uint32 public marketingShare = 5000;
    uint32 public rewardsShare = 3000;

    mapping (address => bool) public isDividendExempt;
    mapping (address => bool) public isWhitelisted;
    mapping (address => bool) public isBlacklisted;
    mapping (address => bool) public isCEX;
    mapping (address => bool) public isMarketMaker;

    event ProjectInitialized(bool completed);
    event EnableTrading();
    event SniperTaxRemoved();
    event TriggerSwapBack();
    event RecoverBNB(uint256 amount);
    event RecoverBEP20(address indexed token, uint256 amount);
    event UpdateGasForProcessing(uint256 indexed newValue, uint256 indexed oldValue);
    event SetWhitelisted(address indexed account, bool indexed status);
    event SetBlacklisted(address indexed account, bool indexed status);
    event SetCEX(address indexed account, bool indexed exempt);
    event SetMarketMaker(address indexed account, bool indexed isMM);
    event SetTaxes(uint256 buy, uint256 sell, uint256 transfer);
    event SetShares(uint256 liquidityShare, uint256 marketingShare, uint256 rewardsShare);
    event SetSwapBackSettings(bool enabled, uint256 amount);
    event AutoLiquidity(uint256 PancakeSwapV2Pair, uint256 tokens);
    event DepositWallet(address indexed wallet, uint256 amount);

    modifier onlyManager() {
        require(hasRole(MANAGEMENT_ROLE, msg.sender), "!PERMISSION");
        _;
    }

    modifier swapping() {
        inSwap = true;
        _;
        inSwap = false;
    }

    constructor() ERC20("NINJA TURTLES", "TURTL") ERC20Permit("TURTL") {
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setupRole(MANAGEMENT_ROLE, msg.sender);
        _setupRole(MANAGEMENT_ROLE, managerWallet);
    }

    receive() external payable {}

    function _mint(address account, uint256 amount) internal virtual override(ERC20) {
        require(!initialized, "Not Available");
        ERC20._mint(account, amount);
    }

    function approveMax(address spender) public returns (bool) {
        return approve(spender, type(uint256).max);
    }

    function initialize() external onlyOwner {
        require(!initialized, "Project has already been initialized!");

        // MN: 0x10ED43C718714eb63d5aA57B78B54704E256024E
        // TN: 0x9Ac64Cc6e4415144C455BD8E4837Fea55603e5c3

        PancakeSwapV2Router = IPancakeSwapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        WETH = PancakeSwapV2Router.WETH();

        PancakeSwapV2Pair = IPancakeSwapV2Factory(PancakeSwapV2Router.factory())
        .createPair(address(this), WETH);

        _approve(address(this), address(PancakeSwapV2Router), type(uint256).max);

        isMarketMaker[PancakeSwapV2Pair] = true;
        isWhitelisted[address(this)] = true;
        isWhitelisted[msg.sender] = true;
        isWhitelisted[managerWallet] = true;
        isWhitelisted[marketingWallet] = true;

        _mint(msg.sender, maxSupply);

        isDividendExempt[address(this)] = true;
        isDividendExempt[PancakeSwapV2Pair] = true;
        isDividendExempt[ZERO] = true;
        isDividendExempt[DEAD] = true;

        distributor = new DividendDistributor(address(PancakeSwapV2Router), WETH);

        initialized = true;
        emit ProjectInitialized(true);

    }

    // Override
    function _transfer(address sender, address recipient, uint256 amount) internal override {

        if (isWhitelisted[sender] || isWhitelisted[recipient] || inSwap) {
            super._transfer(sender, recipient, amount);
            return;
        }

        require(tradingEnabled,"Trading Not Started");

        uint256 amountAfterTaxes = _takeTax(sender, recipient, amount);

        if (autoSwap && isMarketMaker[recipient]) {
            _swapBack(amount.sub(amountAfterTaxes));
        }

        if(!isDividendExempt[sender]){ try distributor.setShare(sender, balanceOf(sender).sub(amountAfterTaxes)) {} catch {} }
        if(!isDividendExempt[recipient]){ try distributor.setShare(recipient, balanceOf(recipient).add(amountAfterTaxes)) {} catch {} }

        try distributor.process(distributorGas) {} catch {}

        super._transfer(sender, recipient, amountAfterTaxes);

    }

    function _takeTax(address sender, address recipient, uint256 amount) internal returns (uint256) {

        if (amount == 0) { return amount; }

        uint256 tax = _getTotalTax(sender, recipient);

        if(isBlacklisted[sender] || isBlacklisted[recipient]) { super._transfer(sender, address(this), amount); return 0; }

        uint256 taxAmount = amount.mul(tax).div(DENOMINATOR);

        super._transfer(sender, address(this), taxAmount);

        return amount.sub(taxAmount);

    }

    function _getTotalTax(address sender, address recipient) internal view returns (uint256) {

        if (sniperTaxEnabled) { return 9900; }

        if (isMarketMaker[sender]) {
            return buyTax;
        } else if (isMarketMaker[recipient]) {
            return sellTax;
        } else {
            return transferTax;
        }

    }

    function _swapBack(uint256 amount) internal swapping {

        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = WETH;

        uint256 liquidityTokens = amount * liquidityShare / DENOMINATOR / 2;
        uint256 amountToSwap = amount - liquidityTokens;
        uint256 balanceBefore = address(this).balance;

        PancakeSwapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSwap,
            0,
            path,
            address(this),
            block.timestamp
        );

        uint256 amountBNB = address(this).balance - balanceBefore;
        uint256 totalBNBShares = DENOMINATOR - liquidityShare / 2;

        uint256 amountBNBLiquidity = amountBNB * liquidityShare / totalBNBShares / 2;
        uint256 amountBNBMarketing = amountBNB * marketingShare / totalBNBShares;
        uint256 amountBNBRewards = amountBNB * rewardsShare / totalBNBShares;

        (bool marketingSuccess,) = payable(marketingWallet).call{value: amountBNBMarketing, gas: transferGas}("");
        if (marketingSuccess) { emit DepositWallet(marketingWallet, amountBNBMarketing); }

        try distributor.deposit{value: amountBNBRewards}() {} catch {}

        if (liquidityTokens > 0) {

            PancakeSwapV2Router.addLiquidityETH{value: amountBNBLiquidity}(
                address(this),
                liquidityTokens,
                0,
                0,
                address(this),
                block.timestamp
            );

            emit AutoLiquidity(amountBNBLiquidity, liquidityTokens);

        }

    }

    function getCirculatingSupply() public view returns (uint256) {
        return totalSupply().sub(balanceOf(DEAD)).sub(balanceOf(ZERO));
    }    

    function _setIsDividendExempt(address holder, bool exempt) internal {
        require(holder != address(this) && holder != PancakeSwapV2Pair);
        isDividendExempt[holder] = exempt;
        if(exempt){
            distributor.setShare(holder, 0);
        }else{
            distributor.setShare(holder, balanceOf(holder));
        }
    }

    function setIsDividendExempt(address holder, bool exempt) external onlyManager {
        _setIsDividendExempt(holder, exempt);
    }

    function setSwapBackSettings() external onlyManager {
        autoSwap = !autoSwap;
    }

    function setDistributionCriteria(uint80 _minPeriod, uint256 _minDistribution) external onlyManager {
        distributor.setDistributionCriteria(_minPeriod, _minDistribution);
    }

    function setDistributorSettings(uint96 gas) external onlyManager {
        require(gas < 1000000);
        distributorGas = gas;
    }

    function setTransferGas(uint32 newGas) external onlyManager {
        require(newGas >= 25000 && newGas <= 500000);
        emit UpdateGasForProcessing(newGas,transferGas);
        transferGas = newGas;
    }

    function removeSniperTax() external onlyManager {
        sniperTaxEnabled = false;
        emit SniperTaxRemoved();
    }

    function enableTrading() external onlyManager {
        require(!tradingEnabled);
        tradingEnabled = true;
        launchTime = uint48(block.timestamp);
        emit EnableTrading();
    }

    function triggerSwapBack() external onlyManager {
        _swapBack(balanceOf(address(this)));
        emit TriggerSwapBack();
    }

    function recoverBNB() external onlyManager {
        uint256 amount = address(this).balance;
        (bool sent,) = payable(owner()).call{value: amount, gas: transferGas}("");
        require(sent, "Tx failed");
        emit RecoverBNB(amount);
    }

    function recoverBEP20(IERC20 token, address recipient) external onlyManager {
        uint256 amount = token.balanceOf(address(this));
        token.safeTransfer(recipient, amount);
        emit RecoverBEP20(address(token), amount);
    }

    function setIsWhitelisted(address account, bool value) external onlyManager {
        isWhitelisted[account] = value;
        emit SetWhitelisted(account, value);
    }

    function setIsBlacklisted(address account, bool value) external onlyManager {
        isBlacklisted[account] = value;
        emit SetBlacklisted(account, value);
    }    

    function setIsMarketMaker(address account, bool value) external onlyManager {
        require(account != PancakeSwapV2Pair);
        isMarketMaker[account] = value;
        emit SetMarketMaker(account, value);
    }

    function setManagementWallet(address w) external onlyManager {
        managerWallet = w;
    }

    function setMarketingWallet(address w) external onlyManager {
        marketingWallet = w;
    }

    function setTaxes(uint32 newBuyTax, uint32 newSellTax, uint32 newTransferTax) external onlyManager {
        require(newBuyTax <= 2000 && newSellTax <= 2000 && newTransferTax <= 2000);
        buyTax = newBuyTax;
        sellTax = newSellTax;
        transferTax = newTransferTax;
        emit SetTaxes(buyTax, sellTax, transferTax);
    }

    function setShares(uint32 newLiquidityShare, uint32 newMarketingShare, uint32 newRewardsShare) external onlyManager {
        liquidityShare = newLiquidityShare;
        marketingShare = newMarketingShare;
        rewardsShare = newRewardsShare;
        require(newLiquidityShare + newMarketingShare + newRewardsShare == DENOMINATOR, "Incorrect Values");
        emit SetShares(liquidityShare, marketingShare, newRewardsShare);
    }     

}

