        if(s.rMarketing > 0 || s.tMarketing > 0) _takeMarketing(s.rMarketing, s.tMarketing);

        if(s.rBuyback > 0 || s.tBuyback > 0) _takeBuyback(s.rBuyback, s.tBuyback);

        if(s.rDev > 0 || s.tDev > 0) _takeDev(s.rDev, s.tDev);

