pragma solidity ^0.8.0;













contract DefiMon is ERC20, Ownable {

    IUniswapV2Router02 public uniswapV2Router;

    address public uniswapV2Pair;

    address payable feeCollector;



    uint256 public transferFee = 11;

    uint256 public discountedTransferFee = 10;

    bool removeFee = false;

    bool tradingEnabled = false;



    mapping(address => bool) public blacklist;

    mapping(address => bool) public excludedFromFee;

    mapping(address => bool) public ammPair;



    event ExcludeFromFee(address _address, bool value);

    event SetBlacklist(address _address, bool value);

    event SetAMMPair(address _address, bool value);



    constructor() ERC20("Defimon Coin", "DFC") {

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E); //BSC



        address _uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());

        uniswapV2Router = _uniswapV2Router;

        uniswapV2Pair = _uniswapV2Pair;

        excludedFromFee[owner()] = true;

        ammPair[_uniswapV2Pair] = true;



        _mint(owner(), 200_000_000 * (10**18));

    }



    receive() external payable {}



    function isBlacklisted(address _address) public view returns(bool) {

        return blacklist[_address];

    }



    function isExcludedFromFee(address _address) public view returns(bool) {

        return excludedFromFee[_address];

    }



    function setFeeCollector(address payable _feeCollector) external onlyOwner {

        feeCollector = _feeCollector;

    }



    function setTransferFee(uint256 _transferFee) external onlyOwner {

        transferFee = _transferFee;

    }



    function setDiscountedTransferFee(uint256 _discountedTransferFee) external onlyOwner {

        discountedTransferFee = _discountedTransferFee;

    }



    function excludeFromFee(address _address, bool value) external onlyOwner {

        require(excludedFromFee[_address] != value, "DFC: Address is already set to value");

        excludedFromFee[_address] = value;

        emit ExcludeFromFee(_address, value);

    }



    function setAMMPair(address _address, bool value) external onlyOwner {

        require(ammPair[_address] != value, "DFC: Address is already set to value");

        ammPair[_address] = value;

        emit SetAMMPair(_address, value);

    }



    function setBlacklist(address _address, bool value) external onlyOwner {

        require(blacklist[_address] != value, "DFC: Address is already set to value");

        blacklist[_address] = value;

        emit SetBlacklist(_address, value);

    }



    function enableTrading() external onlyOwner {

        tradingEnabled = true;

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) internal override {

        if (!tradingEnabled) {

            require(excludedFromFee[from], "DFC: Trading has not started");

        }

        require(!blacklist[from], "DFC: Account is blacklisted");

        bool feeExcluded = removeFee || excludedFromFee[from] || excludedFromFee[to];

        if (!feeExcluded) {

            uint256 fees = amount * transferFee / 100;

            amount -= fees;

            super._transfer(from, address(this), fees);

        }

        if (!ammPair[from] && !feeExcluded && balanceOf(address(this)) > 0) {

            swapAndDistribute(balanceOf(address(this)));

        }

        super._transfer(from, to, amount);

    }



    function swapBNBForTokens(uint256 minTokens) external payable {

        uint256 fee = msg.value * discountedTransferFee / 100;

        uint256 remaining = msg.value - fee;

        feeCollector.call{value: fee}("");

        removeFee = true;

        _swapBNBForTokens(remaining, minTokens, msg.sender);

        removeFee = false;

    }



    function _swapBNBForTokens(uint256 bnbAmount, uint256 minTokens, address _address) internal {

        address[] memory path = new address[](2);

        path[0] = uniswapV2Router.WETH();

        path[1] = address(this);        

        uniswapV2Router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: bnbAmount}(

            minTokens,

            path,

            _address,

            block.timestamp

        );

    }



    function swapAndDistribute(uint256 tokenAmount) public {

        removeFee = true;

        swapTokensForBNB(tokenAmount);

        removeFee = false;

        feeCollector.call{value: address(this).balance}("");

    }



    function swapTokensForBNB(uint256 tokenAmount) internal {

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();

        _approve(address(this), address(uniswapV2Router), tokenAmount);

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0,

            path,

            address(this),

            block.timestamp

        );

    }

}

