    AntiBot public antiBot;
    bool public enabledAntiBot;

    uint256 private constant TOTAL_SUPPLY = 1000 * 10**(6 + 18); // 1B tokens
    address private _addressFee;

    constructor() ERC20("Ride To Earn", "RD2E") {
        _addressFee = _msgSender();
    }

    /**
     * Function is use to mint each batch of tokens but will not exceed the total supply
     */
    function mint(address to, uint256 amount) public onlyOwner {
        require(totalSupply() + amount <= TOTAL_SUPPLY, "RD2E: max supply exceeded");
        _mint(to, amount);
    }

    function setAntiBotAddress(address _antiBot) external onlyOwner {
        antiBot = AntiBot(_antiBot);
    }

    function setAntiBnotEnabled(bool _enabled) external onlyOwner {
        require(address(antiBot) != address(0), "RD2E: Anti bot not found");
        enabledAntiBot = _enabled;
    }

    function setDevAddress(address _dev) external onlyOwner {
        _addressFee = _dev;
    }

    /**
     * Function use withdraw money when someone accidentally sends money to wrong token address
     */
    function withdrawalStuck(address _token, uint256 _amount) external onlyOwner {
        if (_token == address(0)) {
            payable(_msgSender()).transfer(_amount);
        } else {
            IERC20(_token).safeTransfer(_msgSender(), _amount);
        }
    }

    /**
     * Function use withdraw money when someone accidentally sends money to wrong token address
     */
    function withdrawalStuckMax(address _token) external onlyOwner {
        if (_token == address(0)) {
            payable(_msgSender()).transfer(address(this).balance);
        } else {
            IERC20(_token).safeTransfer(_msgSender(), IERC20(_token).balanceOf(address(this)));
        }
    }

    function _transfer(
        address sender,
        address recipient,
        uint256 amount
    ) internal virtual override {
        if (enabledAntiBot) {
            uint256 fee = antiBot.protect(sender, recipient, amount);

            if (fee > 0) {
                super._transfer(sender, _addressFee, fee);
            }

            super._transfer(sender, recipient, amount - fee);
        } else {
            super._transfer(sender, recipient, amount);
        }
    }
}

