    uint256 temp_index = 0;
    for (uint256 i=0; i<len; i++) {
      if (arr_pegout_reserve[id[i]].reg_date > 0) {
        if ( (arr_pegout_reserve[id[i]].user == msg.sender) && (arr_pegout_reserve[id[i]].state == Reserve_state.reserve) ) {
