        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount).sub(rTransferAmount.mul(_rewardFee).div(100-_taxFee-_liquidityFee));

        _rOwned[rewardWallet] = _rOwned[rewardWallet].add(rTransferAmount.mul(_rewardFee).div(100-_taxFee-_liquidityFee));           

        _takeLiquidity(tLiquidity);

        _reflectFee(rFee, tFee);

        emit Transfer(sender, recipient, tTransferAmount);

