   **Description:**  
   The `_lastSell` variable is used in the `transfer` function to enforce a cooldown period. However, it is never initialized. This means that the cooldown period check will always pass, allowing users to transfer tokens immediately after receiving them.  

   **Impact:**  
   Users can transfer tokens immediately after receiving them, bypassing the intended cooldown period. This could lead to front-running attacks or unintended rapid token transfers.  

   **Mitigation:**  
   ```solidity
   uint256 private _lastSell;

   function _transfer(
       address from,
       address to,
       uint256 amount
   ) internal {
       require(from != address(0), "ERC20: transfer from the zero address");
       require(to != address(0), "ERC20: transfer to the zero address");
       require(amount > 0, "Transfer amount must be greater than zero");
       require(
           amount <= balanceOf(from),
           "You are trying to transfer more than your balance"
       );

       if (!_isBlacklisted[from] && !_isBlacklisted[to]) {
           require(tradingEnabled, "Trading not active");
       }

       if (from == pair && !_isBlacklisted[to] && !swapping) {
           require(amount <= maxBuyLimit, "You are exceeding maxBuyLimit");
           require(
               balanceOf(to) + amount <= maxWalletLimit,
               "You are exceeding maxWalletLimit"
           );
       }

       if (
           from != pair && !_isBlacklisted[to] && !_isBlacklisted[from] && !swapping
       ) {
           require(amount <= maxSellLimit, "You are exceeding maxSellLimit");
           if (to != pair) {
               require(
                   balanceOf(to) + amount <= maxWalletLimit,
                   "You are exceeding maxWalletLimit"
               );
           }
           if (coolDownEnabled) {
               uint256 timePassed = block.timestamp - _lastSell[from];
               require(timePassed >= coolDownTime, "Cooldown enabled");
               _lastSell[from] = block.timestamp;
           }
