contract PINUToken is ERC20Capped, ERC20Burnable, Ownable {

    IPinkAntiBot public pinkAntiBot;

    using SafeMath for uint256;

    bool public antiBotEnabled;

    bool public isClaimable;

    address public rewardToken;

    mapping(address => mapping(address => uint256)) public rewardTokenForAddresses;

    mapping(address => mapping(address => uint256)) public rewardAllTokenForAddresses;

    mapping(address => bool) public excludeReward;

    mapping(address => bool) public excludeFee;

    mapping(address => bool) public lpAddresses;

    mapping(uint256 => address) public holders;

    mapping(address => uint256) indexOfHolder;

    mapping(address => bool) public isHolder;

    mapping(address => uint256) public shares;

    mapping(address => bool) public automatedMarketMakerPairs;



    uint256 public totalShares;

    uint256 public totalHolders;

    uint256 public swapTokensAtAmount;

    uint256 maxSupply = 100000000000 * (10 ** 18);

    uint256 minHolder = 20000000 * (10 ** 18);

    uint256 buyRewardFeeRate = 5;

    uint256 buyMarketingFeeRate = 0;

    uint256 sellRewardFeeRate = 5;

    uint256 sellMarketingFeeRate = 5;

    address public marketingAddress;

    bool private swapping;

    IPancakeSwapRouter public router;



    constructor(address pinkAntiBot_, address[] memory pairToken_, address rewardToken_)

    Ownable()

    ERC20Capped(maxSupply)

    ERC20("Pizza Inu", "PINU")

    {

        pinkAntiBot = IPinkAntiBot(pinkAntiBot_);

        pinkAntiBot.setTokenOwner(_msgSender());

        marketingAddress = msg.sender;

        excludeFee[msg.sender] = true;

        excludeReward[msg.sender] = true;

        excludeFee[address(this)] = true;

        excludeReward[address(this)] = true;

        setTokenReward(rewardToken_);

        ERC20._mint(_msgSender(), maxSupply);

        swapTokensAtAmount = 2000 * (10 ** 18);

        router = IPancakeSwapRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        isClaimable = true;

        for (uint256 i = 0; i < pairToken_.length; i++) {

            address pairAddress = IUniswapV2Factory(router.factory()).createPair(address(this), pairToken_[i]);

            setLpAddress(pairAddress, true);

            automatedMarketMakerPairs[pairAddress] = true;

        }

    }



    function _transfer(address sender, address recipient, uint256 amount) internal override(ERC20) {

        require(balanceOf(sender) >= amount, "balance >= amount ");

        uint256 feeRate = 0;

        if (lpAddresses[sender]) {//buy

            feeRate = buyRewardFeeRate + buyMarketingFeeRate;

            if (rewardTokenForAddresses[rewardToken][recipient] > 0 && !isClaimable) {

                _claim(rewardToken, recipient);

            }

        }

        else if (lpAddresses[recipient]) {//sell

            feeRate = sellRewardFeeRate + sellMarketingFeeRate;

        }



        uint256 contractTokenBalance = balanceOf(address(this));



        bool canSwap = contractTokenBalance >= swapTokensAtAmount;



        if (canSwap && !automatedMarketMakerPairs[sender] && !excludeFee[sender] && !excludeFee[recipient] && recipient != marketingAddress && !swapping) {

            swapping = true;

            swapTokensForEth(contractTokenBalance);

            swapping = false;

        }



        bool takefee = !swapping;



        if (feeRate > 0 && takefee && !excludeFee[sender] && !excludeFee[recipient] && recipient != marketingAddress) {

            uint256 fee = amount.mul(feeRate).div(100);

            amount = amount.sub(fee);

            ERC20._transfer(sender, marketingAddress, fee);

        }



        ERC20._transfer(sender, recipient, amount);

        _updateHolder(sender);

        _updateHolder(recipient);

    }



    function swapTokensForEth(uint256 tokenAmount) private {

        // generate the uniswap pair path of token -> weth

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = router.WETH();



        _approve(address(this), address(router), tokenAmount);



        // make the swap

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0, // accept any amount of ETH

            path,

            address(this),

            block.timestamp

        );

    }



    function withdrawToken(address token) external onlyOwner {

        IERC20(token).transfer(msg.sender, IERC20(token).balanceOf(address(this)));

    }



    function withdrawBNB() external onlyOwner {

        payable(msg.sender).transfer(address(this).balance);

    }



    function withdrawAmountBNB(uint256 amount) public onlyOwner {

        payable(msg.sender).transfer(amount);

    }



    receive() external payable {}



    function _updateHolder(address user) internal {

        if (!lpAddresses[user] && !excludeReward[user]) {

            if (balanceOf(user) < minHolder) {

                if (isHolder[user]) {

                    totalShares -= shares[user];

                    shares[user] = 0;

                    isHolder[user] = false;

                    holders[indexOfHolder[user]] = holders[totalHolders - 1];

                    indexOfHolder[holders[totalHolders - 1]] = indexOfHolder[user];

                    delete holders[totalHolders - 1];

                    totalHolders--;

                }

            }

            else {

                if (!isHolder[user]) {

                    totalShares += balanceOf(user);

                    shares[user] = balanceOf(user);

                    isHolder[user] = true;

                    holders[totalHolders] = user;

                    indexOfHolder[user] = totalHolders;

                    totalHolders++;

                } else {

                    totalShares = totalShares - shares[user] + balanceOf(user);

                    shares[user] = balanceOf(user);

                }

            }

        }

    }



    function claim(address _rewardToken) external {

        require(isClaimable, "Can not claim");

        require(rewardTokenForAddresses[rewardToken][msg.sender] > 0, "Nothing to claim");

        _claim(_rewardToken, msg.sender);

    }



    function depositReward(uint256 amount) external onlyOwner {

        IERC20(rewardToken).transferFrom(msg.sender, address(this), amount);

        for (uint256 i; i < totalHolders; i++) {

            rewardTokenForAddresses[rewardToken][holders[i]] += amount.mul(shares[holders[i]]).div(totalShares);

        }

    }



    function _claim(address _rewardToken, address user) internal {

        rewardAllTokenForAddresses[_rewardToken][user] += rewardTokenForAddresses[_rewardToken][user];

        IERC20(_rewardToken).transfer(user, rewardTokenForAddresses[_rewardToken][user]);

        rewardTokenForAddresses[_rewardToken][user] = 0;

    }



    function _mint(address account, uint256 amount) internal virtual override (ERC20, ERC20Capped) {

        ERC20Capped._mint(account, amount);

    }



    // Use this function to control whether to use PinkAntiBot or not instead

    // of managing this in the PinkAntiBot contract

    function setEnableAntiBot(bool _enable) external onlyOwner {

        antiBotEnabled = _enable;

    }



    function setBuyRewardFeeRate(uint256 _fee) external onlyOwner {

        buyRewardFeeRate = _fee;

    }



    function setSellRewardFeeRate(uint256 _fee) external onlyOwner {

        sellRewardFeeRate = _fee;

    }



    function setBuyMarketingFeeRate(uint256 _fee) external onlyOwner {

        buyMarketingFeeRate = _fee;

    }



    function setSellMarketingFeeRate(uint256 _fee) external onlyOwner {

        sellMarketingFeeRate = _fee;

    }



    function viewTransferFee() public view returns (uint256 _buyRewardFeeRate, uint256 _sellRewardFeeRate, uint256 _buyMarketingFeeRate, uint256 _sellMarketingFeeRate){

        return (buyRewardFeeRate, sellRewardFeeRate, buyMarketingFeeRate, sellMarketingFeeRate);

    }



    function getRewardByAddressAndToken(address userAddress, address tokenAddress) public view returns (uint256){

        return rewardTokenForAddresses[tokenAddress][userAddress];

    }



    function getRewardedByAddressAndToken(address userAddress, address tokenAddress) public view returns (uint256) {

        return rewardAllTokenForAddresses[tokenAddress][userAddress];

    }



    function setLpAddress(address _lpAddress, bool _isLp) public onlyOwner {

        lpAddresses[_lpAddress] = _isLp;

    }



    function setExcludeFee(address[] memory _addresses, bool _exclude) external onlyOwner {

        for (uint i = 0; i < _addresses.length; i++) {

            excludeFee[_addresses[i]] = _exclude;

        }

    }



    function setMarketingAddress(address _marketingAddress) external onlyOwner {

        marketingAddress = _marketingAddress;

    }



    function multiExcludeReward(address[] memory addresses, bool isExclude) external onlyOwner {

        for (uint256 i = 0; i < addresses.length; i++) {

            excludeReward[addresses[i]] = isExclude;

        }

    }



    function setTokenReward(address _rewardToken) public onlyOwner {

        rewardToken = _rewardToken;

    }



    function setClaimable(bool _isClaimable) public onlyOwner {

        isClaimable = _isClaimable;

    }



    function setMinHolder(uint256 _minHolder) public onlyOwner {

        if (_minHolder < minHolder) {

            minHolder = _minHolder;

        } else {

            minHolder = _minHolder;

            for (uint256 i; i < totalHolders; i++) {

                _updateHolder(holders[i]);

            }

        }

    }

}

