      }

      if (!inSwap && takeFee) {

        uint256 taxFee = 0;

        if(recipient == pairAddress){

          taxFee = amount.mul(sellTaxFee).div(10000);

        }

        if(sender == pairAddress) {

          taxFee = amount.mul(buyTaxFee).div(10000);

        }

