contract FutuballToken is Context, IERC20, IERC20Metadata,Ownable {



    using SafeMath for uint256;



    mapping(address => uint256) private _balances;



    mapping(address => mapping(address => uint256)) private _allowances;



    uint256 private _totalSupply;

    string private _name = "Futuball Token";

    string private _symbol = "FB";

    uint256 private _initSupply = 100000000*10**18;



    uint256 public sellTaxFee = 500; //take fee while sell token to dex

    uint256 public buyTaxFee = 500; //take fee while sell token to dex

    address public taxAddress;

    bool public feeFlag;

    bool public inSwap;

    address public immutable pairAddress;

    address public immutable routerAddress;



    mapping(address => bool) private _isExcludedFromFee;



    // antiBot

    mapping(address => bool) public addLPaddress;

    uint256 public antiBotAmount;

    uint256 public antiBotStart;

    uint256 public antiBotDuration;



    IPancakeRouter _router = IPancakeRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);



    /**

     * @dev Sets the values for {name} and {symbol}.

     *

     * The default value of {decimals} is 18. To select a different value for

     * {decimals} you should overload it.

     *

     * All two of these values are immutable: they can only be set once during

     * construction.

     */

    constructor() {

        _mint(msg.sender, _initSupply);



        taxAddress = payable(msg.sender);



        pairAddress = IPancakeFactory(_router.factory())

            .createPair(address(this), _router.WETH());



        // set the rest of the contract variables

        routerAddress = address(_router);



        _isExcludedFromFee[owner()] = true;

        _allowances[address(this)][address(_router)] = type(uint256).max;

    }



    function setAddLPAddress(address _address) public onlyOwner 

    { 

        addLPaddress[_address] = true; 

        _isExcludedFromFee[_address] = true;

    }



    function isAntiBotEnded() public view returns (bool) 

    {

        if (antiBotStart == 0) { return false; }

        return block.timestamp > antiBotStart.add(antiBotDuration); 

    }



    function setAntiBotAmount(uint256 _amount, uint256 _duration) public onlyOwner 

    { 

        antiBotAmount = _amount; 

        antiBotDuration = _duration;

        antiBotStart = block.timestamp - 10; // safety margin 10s

    }



    function applyFee(bool flag) public onlyOwner {

      feeFlag = flag;

    }



    function excludeFromFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = true;

    }



    function includeInFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = false;

    }



    function setTaxAddress(address _taxAddress) public onlyOwner {

        taxAddress = _taxAddress;

    }



    function setTax(uint256 _sellTaxFee, uint256 _buyTaxFee) public onlyOwner{

        sellTaxFee = _sellTaxFee;

        buyTaxFee = _buyTaxFee;

    }



    function isExcludedFromFee(address account) public view returns (bool) {

        return _isExcludedFromFee[account];

    }



    function amountForEth(uint256 ethAmount) public view returns(uint256 tokenAmount){

        address _token0Address = IPancakePair(pairAddress).token0();

        address wethAddress = IPancakeRouter(routerAddress).WETH();



        (uint112 _reserve0,uint112 _reserve1,) = IPancakePair(pairAddress).getReserves();

        uint256 _tokenAmount;

        uint256 _wethAmount;

        if(_token0Address==wethAddress){

            _wethAmount = _reserve0;

            _tokenAmount = _reserve1;

        }

        else{

            _wethAmount = _reserve1;

            _tokenAmount = _reserve0;

        }

        tokenAmount = ethAmount.mul(_tokenAmount).div(_wethAmount);

    }



