contract KeyCashGame is Ownable, ReentrancyGuard {

    using SafeERC20 for IERC20;



    bool public started = false;



    uint256 public startPrice = 10**14; // 0.0001 bnb

    uint256 public increasePricePerTicket = 25; // 25/10000000 = 0.00025%

    uint256 public increaseTimePerTicket = 5; // 5 second

    uint256 public numberTicketToDecreaseAdditonalTime = 1000;



    uint256 public currentRound;



    uint256 public shareTicketPriceForPrize = 60;

    uint256 public shareTicketPriceForPlayers = 15;

    uint256 public shareTicketPriceForEarningPlatform = 25;



    uint256 public sharePrizePoolForPrize = 60;

    uint256 public sharePrizePoolForNextRound = 15;

    uint256 public sharePrizePoolAllPlayers = 15;

    uint256 public sharePrizePoolForEarningPlatform = 10;



    uint256 public roundPeriod = 1 days;



    address public addressEarningPlattform;



    uint256 public maxKeysPerTx = 1000;

    mapping(address => bool) public maxKeysPerTxWhitelist;



    mapping(uint256 => mapping(address => BetInfo)) public ledger;

    mapping(uint256 => Round) public rounds;



    struct Round {

        uint256 startTimestamp;

        uint256 closeTimestamp;



        uint256 soldTickets;

        uint256 prizePool;



        uint256 ticketPrice;

        uint256 additionalTime;



        address lastPlayer;

        uint256 lastAmount;

        address winner;

        uint256 winnerPrize;



        uint256 amountForDivident;

        uint256 dividentAmountPerTicket;

    }



    struct BetInfo {

        uint256 ticketAmount;

        bool claimed;

    }



    receive() external payable { }



    function startGame() public onlyOwner {

        require(started == false, "Already started");

        started = true;

        currentRound = 0;

        Round storage curRound = rounds[currentRound];

        curRound.ticketPrice = startPrice;

        curRound.prizePool = 0;

        curRound.startTimestamp = block.timestamp;

        curRound.closeTimestamp = block.timestamp + roundPeriod;

        curRound.additionalTime = increaseTimePerTicket;

    }



    function addWhiteListForBuyingHugeAmount(address wallet, bool isWhitelist) public onlyOwner {

        maxKeysPerTxWhitelist[wallet] = isWhitelist;

    }



    function setMaxKeysPerTx(uint256 _maxKeysPerTx) public onlyOwner {

        maxKeysPerTx = _maxKeysPerTx;

    }



    function buyTickets(uint256 noTicket) public payable nonReentrant{

        require(started, "Game hasn't started yet");

        require(noTicket > 0, "Number ticket must be more than 0");

        require(noTicket <= maxKeysPerTx || maxKeysPerTxWhitelist[msg.sender] , "Number ticket must be less than maxAmount");



        //Check if last round has been finish;

        bool startNewRound = false;

        uint256 nextRoundPrizeAmount;



        Round storage roundCheck = rounds[currentRound];

        if(block.timestamp > roundCheck.closeTimestamp){

            //Send price pool somewhere

            roundCheck.winner = roundCheck.lastPlayer;

            roundCheck.winnerPrize = roundCheck.prizePool * sharePrizePoolForPrize / 100;

            roundCheck.amountForDivident = roundCheck.amountForDivident + roundCheck.prizePool * sharePrizePoolAllPlayers / 100;

            roundCheck.dividentAmountPerTicket = roundCheck.amountForDivident/ roundCheck.soldTickets;

            nextRoundPrizeAmount = roundCheck.prizePool * sharePrizePoolForNextRound / 100;



            uint256 earningPlatfromInPool = roundCheck.prizePool * sharePrizePoolForEarningPlatform / 100;

            try IEarningPlatform(addressEarningPlattform).deposit{value: earningPlatfromInPool}() {} catch {}



            startNewRound =  true;

            currentRound += 1;

        }



        // Current round

        Round storage curRound = rounds[currentRound];

        if(startNewRound){

            curRound.ticketPrice = startPrice;

            curRound.prizePool = nextRoundPrizeAmount;

            curRound.startTimestamp = block.timestamp;

            curRound.closeTimestamp = block.timestamp + roundPeriod;

            curRound.additionalTime = increaseTimePerTicket;

        }



        //Calculate require money

        uint256 totalCost = 0;

        uint256 currentTicketPrice = curRound.ticketPrice;

        for(uint i = 0; i < noTicket; i++){

            totalCost += currentTicketPrice;

            currentTicketPrice = currentTicketPrice + currentTicketPrice * increasePricePerTicket /10000000;

        }

        require(msg.value >= totalCost, "You send mall amount, not enough BNB");

        //Return redundant amount to user

        if(msg.value > totalCost)

            payable(msg.sender).transfer(msg.value - totalCost);



        uint256 remainningTime = curRound.closeTimestamp - block.timestamp;

        if (remainningTime + noTicket*curRound.additionalTime > roundPeriod){

            curRound.closeTimestamp = block.timestamp + roundPeriod;

        }else {

            curRound.closeTimestamp = curRound.closeTimestamp + noTicket*curRound.additionalTime;

        }



        curRound.ticketPrice = currentTicketPrice;

        curRound.lastPlayer = msg.sender;

        curRound.lastAmount = noTicket;

        curRound.soldTickets += noTicket;



        curRound.prizePool += totalCost * shareTicketPriceForPrize / 100;

        curRound.amountForDivident += totalCost * shareTicketPriceForPlayers / 100;



        uint256 amountForEarningPlatfrom  = totalCost * shareTicketPriceForEarningPlatform / 100;

        try IEarningPlatform(addressEarningPlattform).deposit{value: amountForEarningPlatfrom}() {} catch {}   



        //Update number

        ledger[currentRound][msg.sender].ticketAmount += noTicket;



        if(increaseTimePerTicket > curRound.soldTickets / numberTicketToDecreaseAdditonalTime )

            curRound.additionalTime = increaseTimePerTicket - curRound.soldTickets / numberTicketToDecreaseAdditonalTime;

    }





    function getClaimable(address account) public view returns (uint256){

        uint256 claimableAmount;

        for(uint256 i = 0; i < currentRound; i++){

            if(ledger[i][account].ticketAmount > 0 && ledger[i][account].claimed == false) {

                claimableAmount = claimableAmount + ledger[i][account].ticketAmount * rounds[i].dividentAmountPerTicket;



                if(account == rounds[i].winner){

                    claimableAmount = claimableAmount + rounds[i].winnerPrize;

                }

            }

        }

        return claimableAmount;

    }



    function claim() public {

        uint256 amount = getClaimable(msg.sender);

        require(amount > 0, "Claimable amount must be more than 0");



        for(uint256 i = 0; i < currentRound; i++){

            if(ledger[i][msg.sender].ticketAmount > 0 && ledger[i][msg.sender].claimed == false) {

                ledger[i][msg.sender].claimed = true;

            }

        }

        payable(msg.sender).transfer(amount);

    }



    function setTicketPriceShare(uint256 _prizePoolShare, uint256 _distributionForPlayers, uint256 _earningPlatform) public onlyOwner {

        require(_prizePoolShare + _distributionForPlayers + _earningPlatform == 100);

        shareTicketPriceForPrize = _prizePoolShare;

        shareTicketPriceForPlayers = _distributionForPlayers;

        shareTicketPriceForEarningPlatform = _earningPlatform;

    }



    function setPrizePoolShare(uint256 _prizeShare, uint256 _nextRound, uint256 _distributionForPlayers, uint256 _earningPlatform) public onlyOwner {

        require(_prizeShare + _nextRound + _distributionForPlayers + _earningPlatform == 100);

        sharePrizePoolForPrize = _prizeShare;

        sharePrizePoolForNextRound = _nextRound;

        sharePrizePoolAllPlayers = _distributionForPlayers;

        sharePrizePoolForEarningPlatform = _earningPlatform;

    }



    function setStartPrice(uint256 _startPrice) public onlyOwner {

        startPrice = _startPrice;

    }



    function setIncreasePricePerTicket(uint256 _increasePricePerTicket) public onlyOwner {

        increasePricePerTicket = _increasePricePerTicket;

    }



    function setIncreaseTimePerTicket(uint256 _increaseTimePerTicket) public onlyOwner {

        increaseTimePerTicket = _increaseTimePerTicket;

    }



    function setNumberTicketToDecreaseAdditonalTime(uint256 _numberTicketToDecreaseAdditonalTime) public onlyOwner {

        numberTicketToDecreaseAdditonalTime = _numberTicketToDecreaseAdditonalTime;

    }



    function updateEarningPlatform(address _addressEarningPlattform) public onlyOwner {

        addressEarningPlattform = _addressEarningPlattform;

    }



    function updateRoundPeiod(uint256 _periodInSecond) public onlyOwner {

        roundPeriod = _periodInSecond;

    }



    function getTotalKeyBought(address account)public view returns (uint256) {

        uint256 totalKeys = 0;

        for(uint256 i = 0; i < currentRound; i++){

            totalKeys = totalKeys + ledger[i][account].ticketAmount;

        }

        return totalKeys;

    }

}

