        require(
            _now > lastMintDate + 24 hours,
            "Can't generate more tokens today, try again tomorrow"
        );
        lastMintDate = _now;
        _mint(to, amount);
    }

    function transfer(address recipient, uint256 amount)
        public
        virtual
        override
        returns (bool)
    {
        verifyTransaction(recipient, msg.sender);
        if (feeStatus) {
            uint256 cantFee = (amount * 4) / 100;
            uint256 cantBurn = (amount * 1) / 100;
            super.transfer(walletRewards, cantFee);
            burn(cantBurn);
            uint256 totalTransfer = amount - cantFee - cantBurn;
            super.transfer(recipient, totalTransfer);
        } else {
            super.transfer(recipient, amount);
        }

        return true;
    }

