        address sender,
        address recipient,
        uint256 amount
    ) public virtual override returns (bool) {
        verifyTransaction(recipient, sender);
        //the code of the function cannot be compressed any more, since the first one uses 2 parameters and the other, uses 3 parameters
        if (feeStatus) {
