            uint256 cantBurn = (amount * 1) / 100;
            super.transferFrom(sender, walletRewards, cantFee);
            burn(cantBurn);
            uint256 totalTransfer = amount - cantFee - cantBurn;
            super.transferFrom(sender, recipient, totalTransfer);
        } else {
            super.transferFrom(sender, recipient, amount);
        }

        return true;
    }

    function verifyTransaction(address recipientAddress, address sendAddress)
        internal
    {
        require(
            !isBlacklisted[recipientAddress] && !isBlacklisted[sendAddress],
            "The address is on blacklist"
        );

        if (delayBetweenTransfer[sendAddress] > 0) {
            require(
                delayBetweenTransfer[sendAddress] <= block.timestamp,
                "You must wait a bit to make another transaction"
            );
        }
        delayBetweenTransfer[sendAddress] =
            block.timestamp +
            timeDelay *
            1 seconds;
    }

    function changeTimeDelay(uint256 timeChange)
        public
