   **Description:**  
   The `addLiquidity` and `addLiquidityETH` functions can be called by anyone, allowing any user to add liquidity to the contract. This could lead to unauthorized additions of liquidity.

   **Impact:**  
   Unauthorized users could add liquidity to the contract, potentially disrupting the intended distribution of tokens.

   **Mitigation:**  
   ```solidity
   function addLiquidity(
       address tokenA,
       address tokenB,
       uint amountADesired,
       uint amountBDesired,
       uint amountAMin,
       uint amountBMin,
       address to,
       uint deadline
   ) external returns (uint amountA, uint amountB, uint liquidity) {
       require(msg.sender == factoryAddress, "Only factory can add liquidity");
       require(amountADesired >= amountAMin, "Amount A below minimum");
       require(amountBDesired >= amountBMin, "Amount B below minimum");
       uint amountA = amountADesired;
       uint amountB = amountBDesired;
       require(amountA > 0 || amountB > 0, "Amount A or B must be greater than zero");
       require(amountA * amountB > 0, "Amount A or B must be greater than zero");
       uint liquidity = amountA * amountB;
       balances[tokenA] = balances[tokenA].sub(amountADesired);
       balances[tokenB] = balances[tokenB].sub(amountBDesired);
       balances[to] = balances[to].add(liquidity);
       emit Transfer(tokenA, tokenB, amountADesired);
       emit Transfer(tokenB, to, amountBDesired);
       emit Transfer(tokenA, to, amountADesired);
       emit Transfer(tokenB, to, amountBDesired);
       return (amountA, amountB, liquidity);
   }
