contract MANU is Context, IBEP20, Ownable {

    using SafeMath for uint256;

    using Address for address;



    mapping (address => uint256) private _rOwned;

    mapping (address => uint256) private _tOwned;

    mapping (address => mapping (address => uint256)) private _allowances;



    mapping (address => bool) private _isExcludedFromFee;



    mapping (address => bool) private _isExcluded;

    address[] private _excluded;



    uint256 private constant MAX = ~uint256(0);

    uint256 private _tTotal = 10**6 * 10**6 * 10**18;

    uint256 private _rTotal = (MAX - (MAX % _tTotal));

    uint256 private _tFeeTotal;



    string private _name = "Marco Inu";

    string private _symbol = "MANU";

    uint8 private _decimals = 18;



    uint256 public _fee = 1;



    uint256 private _previousFee = _fee;



    IPancakeRouter02 public immutable pancakeRouter;

    address public immutable pancakePair;



    bool inSwapItAndLiquify = false;

    bool public swapItAndLiquifyEnabled = true;



    uint256 private numTokensSellToAddToLiquidity = 10**6 * 10**6 * 10**18;



    struct History {

        uint256 timestamp;

        uint256 amount;

        string status;

    }



    mapping(address => History[]) private _buyHistories;

    // Limit the ability to sell or swap for 0 minutes...

    // 0 seconds = 0 minutes...

    uint256 public _timeLimit = 0;

    address private marketing_address = 0x1828f222e09B4B9c089BF16367041B00647afD25;

    address[] private _accounts;



    event MinTokensBeforeSwapUpdated(uint256 minTokensBeforeSwap);

    event SwapItAndLiquifyEnabledUpdated(bool enabled);

    event SwapItAndLiquify(

        uint256 tokensSwapped,

        uint256 ethReceived,

        uint256 tokensIntoLiquidity

    );



    modifier lockTheSwap {

        inSwapItAndLiquify = true;

        _;

        inSwapItAndLiquify = false;

    }



    constructor () public {

        _rOwned[_msgSender()] = _rTotal;

        _accounts.push(_msgSender());

        // PancakeSwap Router address: (BSC testnet) 0xD99D1c33F9fC3444f8101754aBC46c52416550D1  (BSC mainnet) V2 0x10ED43C718714eb63d5aA57B78B54704E256024E

        IPancakeRouter02 _pancakeRouter = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        _buyHistories[_msgSender()].push(History(block.timestamp, _tTotal, "buy"));

         // Create a pancakeswap pair for this new token

        pancakePair = IPancakeFactory(_pancakeRouter.factory())

            .createPair(address(this), _pancakeRouter.WETH());



        // set the rest of the contract variables

        pancakeRouter = _pancakeRouter;

        //exclude owner and this contract from fee



        _isExcludedFromFee[address(this)] = true;



        emit Transfer(address(0), _msgSender(), _tTotal);

    }



    function name() external view returns (string memory) {

        return _name;

    }



    function symbol() external view returns (string memory) {

        return _symbol;

    }



    function decimals() public view returns (uint8) {

        return _decimals;

    }



    function totalSupply() external view override returns (uint256) {

        return _tTotal;

    }



    function balanceOf(address account) public view override returns (uint256) {

        if (_isExcluded[account]) return _tOwned[account];

        return tokenFromReflection(_rOwned[account]);

    }



    function transfer(address recipient, uint256 amount) external override returns (bool) {

        _transfer(_msgSender(), recipient, amount);

        return true;

    }



    function getBalanceAbleSell(address _address) public view returns(uint256) {

        uint256 allowedAmount = 0;

        string memory buy = "buy";

        string memory sell = "sell";

        for(uint256 i = 0; i < _buyHistories[_address].length; i++) {

            History memory _history = _buyHistories[_address][i];

            if (keccak256(bytes(_history.status)) == keccak256(bytes(buy))) {

                allowedAmount = allowedAmount.add(_history.amount);

            }

            if (keccak256(bytes(_history.status)) == keccak256(bytes(sell))) {

                allowedAmount = allowedAmount.sub(_history.amount);

            }

        }

        return allowedAmount;

    }



    function allowance(address owner, address spender) external view override returns (uint256) {

        return _allowances[owner][spender];

    }



    function approve(address spender, uint256 amount) external override returns (bool) {

        _approve(_msgSender(), spender, amount);

        return true;

    }



    function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {

        _transfer(sender, recipient, amount);

        _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "BEP20: transfer amount exceeds allowance"));

        return true;

    }



    function increaseAllowance(address spender, uint256 addedValue) external virtual returns (bool) {

        _approve(_msgSender(), spender, _allowances[_msgSender()][spender].add(addedValue));

        return true;

    }



    function decreaseAllowance(address spender, uint256 subtractedValue) external virtual returns (bool) {

        _approve(_msgSender(), spender, _allowances[_msgSender()][spender].sub(subtractedValue, "BEP20: decreased allowance below zero"));

        return true;

    }



    function isExcludedFromReward(address account) external view returns (bool) {

        return _isExcluded[account];

    }



    function totalFees() external view returns (uint256) {

        return _tFeeTotal;

    }



    function deliver(uint256 tAmount) external {

        address sender = _msgSender();

        require(!_isExcluded[sender], "Excluded addresses cannot call this function");

        (uint256 rAmount,,,,) = _getValues(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rTotal = _rTotal.sub(rAmount);

        _tFeeTotal = _tFeeTotal.add(tAmount);

    }





    function tokenFromReflection(uint256 rAmount) public view returns(uint256) {

        require(rAmount <= _rTotal, "Amount must be less than total reflections");

        uint256 currentRate =  _getRate();

        return rAmount.div(currentRate);

    }



    function excludeFromReward(address account) public onlyOwner() {

        // require(account != 0x05fF2B0DB69458A0750badebc4f9e13aDd608C7F, 'We can not exclude Pancakeswap router.');

        require(!_isExcluded[account], "Account is already excluded");

        if(_rOwned[account] > 0) {

            _tOwned[account] = tokenFromReflection(_rOwned[account]);

        }

        _isExcluded[account] = true;

        _excluded.push(account);

    }



    function includeInReward(address account) external onlyOwner() {

        require(_isExcluded[account], "Account is not excluded");

        for (uint256 i = 0; i < _excluded.length; i++) {

            if (_excluded[i] == account) {

                _excluded[i] = _excluded[_excluded.length - 1];

                _tOwned[account] = 0;

                _isExcluded[account] = false;

                _excluded.pop();

                break;

            }

        }

    }



    function _transferBothExcluded(address sender, address recipient, uint256 tAmount, uint256 amount_accounts) private {

        (uint256 rAmount, uint256 rTransferAmount, uint256 rBurn, uint256 tTransferAmount, uint256 tLiquidity) = _getValues(tAmount);

        _tOwned[sender] = _tOwned[sender].sub(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _tOwned[recipient] = _tOwned[recipient].add(tTransferAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);     





        _rOwned[marketing_address] = _rOwned[marketing_address].add(rBurn);

        _buyHistories[marketing_address].push(History(block.timestamp, tLiquidity, "buy"));        

        _tTotal = _tTotal.sub(tLiquidity);

        _buyHistories[recipient].push(History(block.timestamp, tTransferAmount, "buy"));

        _buyHistories[sender].push(History(block.timestamp, tAmount, "sell"));



        if (amount_accounts != 0) {

            uint256 _sReward = rBurn.div(amount_accounts);

            uint256 _tReward = tLiquidity.div(amount_accounts);



            for (uint256 i = 0; i < _accounts.length; i ++) {

                address _temp = _accounts[i];

                if (_temp != sender && _temp != recipient) {

                    _rOwned[_temp] = _rOwned[_temp].add(_sReward);

                    _buyHistories[_temp].push(History(block.timestamp, _tReward, "buy"));

                }

            }

        }





        _takeLiquidity(tLiquidity);

        _reflectFee(rBurn, tLiquidity);

        emit Transfer(sender, recipient, tTransferAmount);

        emit Transfer(sender, marketing_address, tLiquidity);

        emit Transfer(sender, pancakePair, tLiquidity);

        emit Transfer(owner(), address(0), tLiquidity);



    }



    function excludeFromFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = true;

    }



    function includeInFee(address account) public onlyOwner {

        _isExcludedFromFee[account] = false;

    }



    function setSwapItAndLiquifyEnabled(bool _enabled) public onlyOwner {

        swapItAndLiquifyEnabled = _enabled;

        emit SwapItAndLiquifyEnabledUpdated(_enabled);

    }



     //to receive BNB from pancakeRouter when swapping

    receive() external payable {}



    /// This will allow to rescue BNB sent by mistake directly to the contract

    function rescueBNBFromContract() external onlyOwner {

        address payable _owner = _msgSender();

        _owner.transfer(address(this).balance);

    }



    function _reflectFee(uint256 rFee, uint256 tFee) private {

        _rTotal = _rTotal.sub(rFee);

        _tFeeTotal = _tFeeTotal.add(tFee);

    }



    function _getValues(uint256 tAmount) private view returns (uint256, uint256, uint256, uint256, uint256) {

        (uint256 tTransferAmount, uint256 tFee) = _getTValues(tAmount);

        (uint256 rAmount, uint256 rTransferAmount, uint256 rFee) = _getRValues(tAmount, tFee, _getRate());

        return (rAmount, rTransferAmount, rFee, tTransferAmount, tFee);

    }



    function _getTValues(uint256 tAmount) private view returns (uint256, uint256) {

        uint256 tFee = calculateFee(tAmount);

        uint256 tTransferAmount = tAmount.sub(tFee.mul(4));

        return (tTransferAmount, tFee);

    }



    function _getRValues(uint256 tAmount, uint256 tFee, uint256 currentRate) private pure returns (uint256, uint256, uint256) {

        uint256 rAmount = tAmount.mul(currentRate);

        uint256 rFee = tFee.mul(currentRate);

        uint256 rTransferAmount = rAmount.sub(rFee.mul(4));

        return (rAmount, rTransferAmount, rFee);

    }



    function _getRate() private view returns(uint256) {

        (uint256 rSupply, uint256 tSupply) = _getCurrentSupply();

        return rSupply.div(tSupply);

    }



    function _getCurrentSupply() private view returns(uint256, uint256) {

        uint256 rSupply = _rTotal;

        uint256 tSupply = _tTotal;      

        for (uint256 i = 0; i < _excluded.length; i++) {

            if (_rOwned[_excluded[i]] > rSupply || _tOwned[_excluded[i]] > tSupply) return (_rTotal, _tTotal);

            rSupply = rSupply.sub(_rOwned[_excluded[i]]);

            tSupply = tSupply.sub(_tOwned[_excluded[i]]);

        }

        if (rSupply < _rTotal.div(_tTotal)) return (_rTotal, _tTotal);

        return (rSupply, tSupply);

    }



    function _takeLiquidity(uint256 tLiquidity) private {

        uint256 currentRate =  _getRate();

        uint256 rLiquidity = tLiquidity.mul(currentRate);

        _rOwned[address(this)] = _rOwned[address(this)].add(rLiquidity);

        if(_isExcluded[address(this)])

            _tOwned[address(this)] = _tOwned[address(this)].add(tLiquidity);

    }



    function calculateFee(uint256 _amount) private view returns (uint256) {

        return _amount.mul(_fee).div(

            10**2

        );

    }



    function removeAllFee() private {

        if(_fee == 0) return;



        _previousFee = _fee;



        _fee = 0;

    }



    function restoreAllFee() private {

        _fee = _previousFee;

    }



    function isExcludedFromFee(address account) public view returns(bool) {

        return _isExcludedFromFee[account];

    }



    function _approve(address owner, address spender, uint256 amount) private {

        require(owner != address(0), "BEP20: approve from the zero address");

        require(spender != address(0), "BEP20: approve to the zero address");



        _allowances[owner][spender] = amount;

        emit Approval(owner, spender, amount);

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) private {

        require(from != address(0), "BEP20: transfer from the zero address");

        require(to != address(0), "BEP20: transfer to the zero address");

        require(amount > 0, "Transfer amount must be greater than zero");

        uint256 senderBalance = _rOwned[from];

        require(senderBalance >= amount, "Transfer amount exceeds balance");



        uint256 recipientBalance = _rOwned[to].div(_getRate());



        require((recipientBalance + amount) <= (_tTotal / 1), "Sorry, nobody can own more than 100% of the total supply.");



        if (!((from == address(this) && to == pancakePair) || from == pancakePair || (to == pancakePair && from == _accounts[0]))) {

            string memory buy = "buy";

            string memory sell = "sell";

            uint256 allowedAmount = 0;

            for(uint256 i = 0; i < _buyHistories[from].length; i++) {

                History memory _history = _buyHistories[from][i];

                if (keccak256(bytes(_history.status)) == keccak256(bytes(buy))) {

                    allowedAmount = allowedAmount.add(_history.amount);

                }

                if (keccak256(bytes(_history.status)) == keccak256(bytes(sell))) {

                    allowedAmount = allowedAmount.sub(_history.amount);

                }

            }



            require(amount <= allowedAmount && allowedAmount <= _tTotal, "Sorry, sell/swap locked over buying.");

        }



        uint256 count = 0;

        for (uint256 i = 0; i < _accounts.length; i ++) {

            if (_accounts[i] == to)

                count ++;

        }

        if (count == 0) {

            _accounts.push(to);

        }



        uint256 amount_accounts = _accounts.length;

        if (amount_accounts > 2) {

            amount_accounts = amount_accounts.sub(2);            

        }



        // is the token balance of this contract address over the min number of

        // tokens that we need to initiate a swap + liquidity lock?

        // also, don't get caught in a circular liquidity event.

        // also, don't swap & liquify if sender is pancake pair.

        uint256 contractTokenBalance = balanceOf(address(this));



        bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;

        if (

            overMinTokenBalance &&

            !inSwapItAndLiquify &&

            from != pancakePair &&

            swapItAndLiquifyEnabled

        ) {

            contractTokenBalance = numTokensSellToAddToLiquidity;

            //add liquidity

            _swapItAndLiquify(contractTokenBalance);

        }



        //indicates if fee should be deducted from transfer

        bool takeFee = true;



        //if any account belongs to _isExcludedFromFee account then remove the fee

        if(_isExcludedFromFee[from] || _isExcludedFromFee[to]){

            takeFee = false;

        }



        //transfer amount, it will take tax, burn, liquidity fee

        _tokenTransfer(from,to,amount, amount_accounts, takeFee);





    }



    function _swapItAndLiquify(uint256 contractTokenBalance) private lockTheSwap {

        // split the contract balance into halves

        uint256 half = contractTokenBalance.div(2);

        uint256 otherHalf = contractTokenBalance.sub(half);



        // capture the contract's current BNB balance.

        // this is so that we can capture exactly the amount of BNB that the

        // swap creates, and not make the liquidity event include any BNB that

        // has been manually sent to the contract

        uint256 initialBalance = address(this).balance;



        // swap tokens for BNB

        swapTokensForBNB(half); // <- this breaks the BNB -> HATE swap when swap+liquify is triggered



        // how much BNB did we just swap into?

        uint256 newBalance = address(this).balance.sub(initialBalance);



        // add liquidity to pancakswap

        addLiquidity(otherHalf, newBalance);



        emit SwapItAndLiquify(half, newBalance, otherHalf);

    }



    function swapTokensForBNB(uint256 tokenAmount) private {

        // generate the pancakeswap pair path of token -> weth

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = pancakeRouter.WETH();



        _approve(address(this), address(pancakeRouter), tokenAmount);



        // make the swap

        pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0, // accept any amount of BNB

            path,

            address(this),

            block.timestamp

        );

    }



    function addLiquidity(uint256 tokenAmount, uint256 bnbAmount) private {

        // approve token transfer to cover all possible scenarios

        _approve(address(this), address(pancakeRouter), tokenAmount);



        // add the liquidity

        pancakeRouter.addLiquidityETH{value: bnbAmount}(

            address(this),

            tokenAmount,

            0, // slippage is unavoidable

            0, // slippage is unavoidable

            owner(),

            block.timestamp

        );

    }



    //this method is responsible for taking all fee, if takeFee is true

    function _tokenTransfer(address sender, address recipient, uint256 amount, uint256 amount_accounts, bool takeFee) private {

	    if(!takeFee)

            removeAllFee();



        if (_isExcluded[sender] && !_isExcluded[recipient]) {

            _transferFromExcluded(sender, recipient, amount, amount_accounts);

        } else if (!_isExcluded[sender] && _isExcluded[recipient]) {

            _transferToExcluded(sender, recipient, amount, amount_accounts);

        } else if (_isExcluded[sender] && _isExcluded[recipient]) {

            _transferBothExcluded(sender, recipient, amount, amount_accounts);

        } else {

            _transferStandard(sender, recipient, amount, amount_accounts);

	    }



        if(!takeFee)

            restoreAllFee();

    }



    function _transferStandard(address sender, address recipient, uint256 tAmount, uint256 amount_accounts) private {

        (uint256 rAmount, uint256 rTransferAmount, uint256 rBurn, uint256 tTransferAmount, uint256 tLiquidity) = _getValues(tAmount);



        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);



        _rOwned[marketing_address] = _rOwned[marketing_address].add(rBurn);

        _buyHistories[marketing_address].push(History(block.timestamp, tLiquidity, "buy"));        

        _tTotal = _tTotal.sub(tLiquidity);

        _buyHistories[recipient].push(History(block.timestamp, tTransferAmount, "buy"));

        _buyHistories[sender].push(History(block.timestamp, tAmount, "sell"));



        if (amount_accounts != 0) {

            uint256 _sReward = rBurn.div(amount_accounts);

            uint256 _tReward = tLiquidity.div(amount_accounts);



            for (uint256 i = 0; i < _accounts.length; i ++) {

                address _temp = _accounts[i];

                if (_temp != sender && _temp != recipient) {

                    _rOwned[_temp] = _rOwned[_temp].add(_sReward);

                    _buyHistories[_temp].push(History(block.timestamp, _tReward, "buy"));

                }

            }

        }



        _takeLiquidity(tLiquidity);

        _reflectFee(rBurn, tLiquidity);

        emit Transfer(sender, recipient, tTransferAmount);

        emit Transfer(sender, marketing_address, tLiquidity);

        emit Transfer(sender, pancakePair, tLiquidity);

        emit Transfer(owner(), address(0), tLiquidity);



    }



    function _transferToExcluded(address sender, address recipient, uint256 tAmount, uint256 amount_accounts) private {

        (uint256 rAmount, uint256 rTransferAmount, uint256 rBurn, uint256 tTransferAmount, uint256 tLiquidity) = _getValues(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _tOwned[recipient] = _tOwned[recipient].add(tTransferAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);  



        _rOwned[marketing_address] = _rOwned[marketing_address].add(rBurn);

        _buyHistories[marketing_address].push(History(block.timestamp, tLiquidity, "buy"));        

        _tTotal = _tTotal.sub(tLiquidity);

        _buyHistories[recipient].push(History(block.timestamp, tTransferAmount, "buy"));

        _buyHistories[sender].push(History(block.timestamp, tAmount, "sell"));



        if (amount_accounts != 0) {

            uint256 _sReward = rBurn.div(amount_accounts);

            uint256 _tReward = tLiquidity.div(amount_accounts);



            for (uint256 i = 0; i < _accounts.length; i ++) {

                address _temp = _accounts[i];

                if (_temp != sender && _temp != recipient) {

                    _rOwned[_temp] = _rOwned[_temp].add(_sReward);

                    _buyHistories[_temp].push(History(block.timestamp, _tReward, "buy"));

                }

            }

        }



        _takeLiquidity(tLiquidity);

        _reflectFee(rBurn, tLiquidity);

        emit Transfer(sender, recipient, tTransferAmount);

        emit Transfer(sender, marketing_address, tLiquidity);

        emit Transfer(sender, pancakePair, tLiquidity);

        emit Transfer(owner(), address(0), tLiquidity);

    }



    function _transferFromExcluded(address sender, address recipient, uint256 tAmount, uint256 amount_accounts) private {

        (uint256 rAmount, uint256 rTransferAmount, uint256 rBurn, uint256 tTransferAmount, uint256 tLiquidity) = _getValues(tAmount);

        _tOwned[sender] = _tOwned[sender].sub(tAmount);

        _rOwned[sender] = _rOwned[sender].sub(rAmount);

        _rOwned[recipient] = _rOwned[recipient].add(rTransferAmount);   



        _rOwned[marketing_address] = _rOwned[marketing_address].add(rBurn);

        _buyHistories[marketing_address].push(History(block.timestamp, tLiquidity, "buy"));        

        _tTotal = _tTotal.sub(tLiquidity);

        _buyHistories[recipient].push(History(block.timestamp, tTransferAmount, "buy"));

        _buyHistories[sender].push(History(block.timestamp, tAmount, "sell"));



        if (amount_accounts != 0) {

            uint256 _sReward = rBurn.div(amount_accounts);

            uint256 _tReward = tLiquidity.div(amount_accounts);



            for (uint256 i = 0; i < _accounts.length; i ++) {

